/**
 * errors.js
 *
 * Centralised custom error classes for the Express application.
 * Every class extends the built-in Error so that:
 *   - instanceof checks work correctly up the prototype chain
 *   - stack traces are captured automatically
 *   - Express's centralised error handler can branch on type / statusCode
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

/**
 * AppError is the root class for all application-level errors.
 *
 * @param {string}  message        - Human-readable description of the problem.
 * @param {number}  statusCode     - HTTP status code to be sent to the client.
 * @param {string}  code           - Machine-readable error code (e.g. "NOT_FOUND").
 * @param {boolean} isOperational  - true  → expected/handled error (don't crash).
 *                                   false → programmer error (may want to crash).
 */
class AppError extends Error {
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Restore prototype chain (required when extending built-ins in ES5 targets)
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = new.target.name; // e.g. "NotFoundError"
    this.statusCode  = statusCode;
    this.code        = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that omits the constructor frame itself
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, new.target);
    }
  }

  /**
   * Serialise the error into a plain object safe to send as a JSON response.
   * The stack is intentionally excluded from the public payload.
   */
  toJSON() {
    return {
      error: {
        name:    this.name,
        code:    this.code,
        message: this.message,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 404 Not Found
// ---------------------------------------------------------------------------

/**
 * Thrown when a requested resource cannot be located.
 *
 * HTTP 404 Not Found
 *
 * @example
 *   throw new NotFoundError('User not found', 'USER_NOT_FOUND');
 *   throw new NotFoundError(`Product ${id} does not exist`);
 */
class NotFoundError extends AppError {
  /**
   * @param {string} message  - Description of what was not found.
   * @param {string} [code]   - Optional machine-readable code; defaults to "NOT_FOUND".
   */
  constructor(message = 'The requested resource was not found', code = 'NOT_FOUND') {
    super(message, 404, code);
  }
}

// ---------------------------------------------------------------------------
// 422 Validation Error
// ---------------------------------------------------------------------------

/**
 * Thrown when incoming request data fails validation rules.
 *
 * HTTP 422 Unprocessable Entity
 *
 * @example
 *   throw new ValidationError('Email is required');
 *   throw new ValidationError('Invalid payload', 'INVALID_EMAIL', [
 *     { field: 'email', message: 'Must be a valid email address' },
 *   ]);
 */
class ValidationError extends AppError {
  /**
   * @param {string}   message    - Top-level description of the validation failure.
   * @param {string}   [code]     - Machine-readable code; defaults to "VALIDATION_ERROR".
   * @param {Array}    [details]  - Optional array of field-level error objects,
   *                                e.g. [{ field: 'email', message: '...' }].
   */
  constructor(
    message = 'The provided data is invalid',
    code    = 'VALIDATION_ERROR',
    details = [],
  ) {
    super(message, 422, code);
    this.details = details; // field-level breakdown, may be empty
  }

  /** Override to include field-level details in the serialised response. */
  toJSON() {
    const base = super.toJSON();
    if (this.details && this.details.length > 0) {
      base.error.details = this.details;
    }
    return base;
  }
}

// ---------------------------------------------------------------------------
// 503 Database Error
// ---------------------------------------------------------------------------

/**
 * Thrown when an interaction with the database fails (connection lost,
 * query timeout, constraint violation that wasn't caught earlier, etc.).
 *
 * HTTP 503 Service Unavailable — signals a transient infrastructure problem
 * that the client may retry, without leaking internal database details.
 *
 * @example
 *   throw new DatabaseError('Connection pool exhausted');
 *   throw new DatabaseError('Query timed out', 'DB_TIMEOUT', originalError);
 */
class DatabaseError extends AppError {
  /**
   * @param {string} message      - Description safe to surface externally.
   * @param {string} [code]       - Machine-readable code; defaults to "DATABASE_ERROR".
   * @param {Error}  [cause]      - Original low-level error for server-side logging.
   */
  constructor(
    message = 'A database error occurred',
    code    = 'DATABASE_ERROR',
    cause   = null,
  ) {
    // DatabaseError is treated as operational (infrastructure blip, not a bug)
    super(message, 503, code, true);
    this.cause = cause; // kept for logging; never forwarded to the client
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

'use strict';

/**
 * app.js
 *
 * Express application with:
 *  - Route handlers that throw typed errors instead of inlining res.status().json()
 *  - A centralised error-handling middleware (4-argument signature) that is the
 *    single place responsible for logging and sending error responses
 */

const express = require('express');
const { NotFoundError, ValidationError, DatabaseError, AppError } = require('./errors');

const app = express();

// ---------------------------------------------------------------------------
// Request parsing
// ---------------------------------------------------------------------------
app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 *
 * Simple liveness probe – never throws, always returns 200.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 *
 * Returns the full list of users.
 * Demonstrates: no error path needed (in-memory data always resolves).
 */
app.get('/users', (req, res) => {
  // Static in-memory dataset – replace with a real DB query as needed.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];
  res.json(users);
});

/**
 * GET /users/:id
 *
 * Returns a single user by numeric ID.
 * Demonstrates: NotFoundError and ValidationError thrown from route handler.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  // Guard: id must be a positive integer
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError(
      `"${req.params.id}" is not a valid user ID – expected a positive integer`,
      'INVALID_USER_ID',
    );
  }

  // Static in-memory dataset – replace with a real DB query as needed.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];
  const user = users.find((u) => u.id === id);

  if (!user) {
    throw new NotFoundError(`User with ID ${id} was not found`, 'USER_NOT_FOUND');
  }

  res.json(user);
});

/**
 * POST /users
 *
 * Creates a new user.
 * Demonstrates: ValidationError with field-level details.
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};
  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'name is required and must be a non-empty string' });
  }

  if (!email || typeof email !== 'string') {
    fieldErrors.push({ field: 'email', message: 'email is required and must be a string' });
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    fieldErrors.push({ field: 'email', message: 'email must be a valid email address' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Request body contains invalid fields', 'INVALID_USER_PAYLOAD', fieldErrors);
  }

  // Simulate a successful creation (no real persistence here).
  const newUser = { id: Date.now(), name: name.trim(), email };
  res.status(201).json(newUser);
});

/**
 * GET /users/:id/orders
 *
 * Returns orders for a specific user.
 * Demonstrates: DatabaseError thrown from route handler.
 */
app.get('/users/:id/orders', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError(
      `"${req.params.id}" is not a valid user ID – expected a positive integer`,
      'INVALID_USER_ID',
    );
  }

  // Simulate a transient database failure for demonstration purposes.
  // Replace with a real query that may throw DatabaseError on catch.
  const dbAvailable = true; // toggle to false to exercise the DatabaseError path
  if (!dbAvailable) {
    throw new DatabaseError('Orders database is temporarily unavailable', 'DB_UNAVAILABLE');
  }

  // Return empty orders list for existing users
  res.json({ userId: id, orders: [] });
});

// ---------------------------------------------------------------------------
// 404 catch-all  (must come AFTER all real routes)
// ---------------------------------------------------------------------------

/**
 * Any request that reaches here matched no route.
 * We throw a NotFoundError so the centralised handler formats the response.
 */
app.use((req, _res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.path} does not exist`, 'ROUTE_NOT_FOUND'));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
// ---------------------------------------------------------------------------

/**
 * errorHandler
 *
 * Express identifies this as an error-handling middleware because it declares
 * exactly four parameters (err, req, res, next).  It MUST be registered after
 * all routes and other middleware.
 *
 * Responsibilities:
 *  1. Log the error server-side (stack for unexpected errors, brief message for
 *     operational ones).
 *  2. Decide whether the error is one we recognise (AppError subclass) or an
 *     unknown/programmer error.
 *  3. Send a consistent JSON response – never leaking internal stack traces or
 *     raw database messages to the client.
 */
// eslint-disable-next-line no-unused-vars
function errorHandler(err, req, res, next) {
  // --- 1. Server-side logging -----------------------------------------------
  if (err instanceof AppError && err.isOperational) {
    // Expected errors: a one-liner is sufficient
    console.error(`[${err.code}] ${err.message}`);

    // Log the root cause for DatabaseErrors (never sent to client)
    if (err.cause) {
      console.error('Caused by:', err.cause);
    }
  } else {
    // Unexpected/programmer errors: log the full stack so we can debug
    console.error('Unexpected error:', err);
  }

  // --- 2. Determine status code & response body -----------------------------
  if (err instanceof AppError) {
    // Known, typed error – use its own status code and serialiser
    return res.status(err.statusCode).json(err.toJSON());
  }

  // Unknown error – do NOT expose internals; return a generic 500
  return res.status(500).json({
    error: {
      name:    'InternalServerError',
      code:    'INTERNAL_SERVER_ERROR',
      message: 'An unexpected error occurred. Please try again later.',
    },
  });
}

app.use(errorHandler);

// ---------------------------------------------------------------------------
// Server bootstrap (skipped when required by tests)
// ---------------------------------------------------------------------------
/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

