# Verify the error classes load and behave correctly
node -e "
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

// --- AppError base ---
const base = new AppError('base msg', 400, 'BASE_CODE');
console.assert(base instanceof Error,    'AppError should extend Error');
console.assert(base instanceof AppError, 'AppError instanceof AppError');
console.assert(base.statusCode === 400,  'AppError.statusCode');
console.assert(base.code === 'BASE_CODE','AppError.code');
console.assert(base.isOperational === true, 'AppError.isOperational default');
console.assert(JSON.stringify(base.toJSON()).includes('BASE_CODE'), 'AppError.toJSON includes code');
console.log('AppError OK');

// --- NotFoundError ---
const nfe = new NotFoundError('User not found', 'USER_NOT_FOUND');
console.assert(nfe instanceof AppError,      'NotFoundError extends AppError');
console.assert(nfe instanceof NotFoundError, 'NotFoundError instanceof NotFoundError');
console.assert(nfe.statusCode === 404,       'NotFoundError.statusCode === 404');
console.assert(nfe.code === 'USER_NOT_FOUND','NotFoundError.code');
console.assert(nfe.name === 'NotFoundError', 'NotFoundError.name');
console.log('NotFoundError OK');

// --- NotFoundError defaults ---
const nfeDef = new NotFoundError();
console.assert(nfeDef.statusCode === 404,  'NotFoundError default statusCode');
console.assert(nfeDef.code === 'NOT_FOUND','NotFoundError default code');
console.log('NotFoundError defaults OK');

// --- ValidationError ---
const details = [{ field: 'email', message: 'invalid' }];
const ve = new ValidationError('Bad input', 'INVALID_EMAIL', details);
console.assert(ve instanceof AppError,         'ValidationError extends AppError');
console.assert(ve instanceof ValidationError,  'ValidationError instanceof');
console.assert(ve.statusCode === 422,          'ValidationError.statusCode === 422');
console.assert(ve.code === 'INVALID_EMAIL',    'ValidationError.code');
console.assert(ve.details.length === 1,        'ValidationError.details populated');
const veJSON = ve.toJSON();
console.assert(veJSON.error.details[0].field === 'email', 'ValidationError.toJSON includes details');
console.log('ValidationError OK');

// --- ValidationError with no details omits details key ---
const veNoDetails = new ValidationError('Missing name');
const veNoJSON    = veNoDetails.toJSON();
console.assert(!veNoJSON.error.details, 'ValidationError.toJSON omits empty details');
console.log('ValidationError no-details OK');

// --- ValidationError defaults ---
const veDef = new ValidationError();
console.assert(veDef.statusCode === 422,            'ValidationError default statusCode');
console.assert(veDef.code === 'VALIDATION_ERROR',   'ValidationError default code');
console.log('ValidationError defaults OK');

// --- DatabaseError ---
const cause = new Error('pg: connection refused');
const dbe = new DatabaseError('DB unavailable', 'DB_DOWN', cause);
console.assert(dbe instanceof AppError,       'DatabaseError extends AppError');
console.assert(dbe instanceof DatabaseError,  'DatabaseError instanceof');
console.assert(dbe.statusCode === 503,        'DatabaseError.statusCode === 503');
console.assert(dbe.cause === cause,           'DatabaseError.cause stored');
const dbeJSON = dbe.toJSON();
console.assert(!JSON.stringify(dbeJSON).includes('pg:'), 'DatabaseError.toJSON never leaks cause');
console.log('DatabaseError OK');

// --- DatabaseError defaults ---
const dbeDef = new DatabaseError();
console.assert(dbeDef.statusCode === 503,          'DatabaseError default statusCode');
console.assert(dbeDef.code === 'DATABASE_ERROR',   'DatabaseError default code');
console.assert(dbeDef.cause === null,              'DatabaseError default cause');
console.log('DatabaseError defaults OK');

console.log('All error class assertions passed.');
"

# Full integration smoke-test against the live app
node -e "
const http = require('http');
const app  = require('./app');

const server = app.listen(0, async () => {
  const { port } = server.address();
  const base = \`http://localhost:\${port}\`;

  async function req(method, path, body) {
    return new Promise((resolve, reject) => {
      const opts = {
        method,
        hostname: 'localhost',
        port,
        path,
        headers: { 'Content-Type': 'application/json' },
      };
      const r = http.request(opts, (res) => {
        let data = '';
        res.on('data', (c) => (data += c));
        res.on('end', () => {
          try { resolve({ status: res.statusCode, body: JSON.parse(data) }); }
          catch(e) { resolve({ status: res.statusCode, body: data }); }
        });
      });
      r.on('error', reject);
      if (body) r.write(JSON.stringify(body));
      r.end();
    });
  }

  const tests = [];

  // 1. GET /health -> 200
  const health = await req('GET', '/health');
  tests.push(['GET /health → 200',          health.status === 200]);
  tests.push(['GET /health body.status=ok', health.body.status === 'ok']);

  // 2. GET /users -> 200, array
  const users = await req('GET', '/users');
  tests.push(['GET /users → 200',           users.status === 200]);
  tests.push(['GET /users is array',        Array.isArray(users.body)]);

  // 3. GET /users/1 -> 200
  const user1 = await req('GET', '/users/1');
  tests.push(['GET /users/1 → 200',         user1.status === 200]);
  tests.push(['GET /users/1 name=Alice',    user1.body.name === 'Alice']);

  // 4. GET /users/99 -> 404 NotFoundError
  const u99 = await req('GET', '/users/99');
  tests.push(['GET /users/99 → 404',        u99.status === 404]);
  tests.push(['GET /users/99 code',         u99.body.error.code === 'USER_NOT_FOUND']);

  // 5. GET /users/abc -> 422 ValidationError
  const uabc = await req('GET', '/users/abc');
  tests.push(['GET /users/abc → 422',       uabc.status === 422]);
  tests.push(['GET /users/abc code',        uabc.body.error.code === 'INVALID_USER_ID']);

  // 6. POST /users valid -> 201
  const created = await req('POST', '/users', { name: 'Carol', email: 'carol@example.com' });
  tests.push(['POST /users valid → 201',    created.status === 201]);
  tests.push(['POST /users name=Carol',     created.body.name === 'Carol']);

  // 7. POST /users missing fields -> 422
  const badPost = await req('POST', '/users', {});
  tests.push(['POST /users empty → 422',    badPost.status === 422]);
  tests.push(['POST /users details array',  Array.isArray(badPost.body.error.details)]);
  tests.push(['POST /users 2 field errors', badPost.body.error.details.length === 2]);

  // 8. GET /users/1/orders -> 200
  const orders = await req('GET', '/users/1/orders');
  tests.push(['GET /users/1/orders → 200',  orders.status === 200]);

  // 9. GET /nonexistent -> 404 catch-all
  const miss = await req('GET', '/nonexistent');
  tests.push(['GET /nonexistent → 404',     miss.status === 404]);
  tests.push(['GET /nonexistent code',      miss.body.error.code === 'ROUTE_NOT_FOUND']);

  // --- report
  let passed = 0, failed = 0;
  for (const [label, ok] of tests) {
    if (ok) { console.log('  PASS:', label); passed++; }
    else     { console.error('  FAIL:', label); failed++; }
  }
  console.log(\`\nResults: \${passed} passed, \${failed} failed.\`);
  server.close(() => process.exit(failed > 0 ? 1 : 0));
});
"

