/**
 * errors.js
 * Centralised custom error classes for the Express application.
 *
 * Every class extends the built-in Error and carries:
 *   - statusCode  – the HTTP status code that should be sent to the client
 *   - code        – a stable machine-readable string identifier
 *   - isOperational – true for "expected" errors (invalid input, missing
 *                     resource, …) so the global handler can distinguish them
 *                     from unexpected programmer errors.
 */

'use strict';

// ─── Base Application Error ───────────────────────────────────────────────────

class AppError extends Error {
  /**
   * @param {string}  message      - Human-readable description of the error.
   * @param {number}  statusCode   - HTTP status code (e.g. 404, 422, 500).
   * @param {string}  code         - Machine-readable error identifier.
   * @param {boolean} isOperational - Whether this is an expected operational
   *                                  error (true) or a programmer mistake (false).
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Maintain a clean prototype chain so `instanceof` checks keep working
    // even after TypeScript / Babel transpilation.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.code        = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call-site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /**
   * Serialise the error into a plain object safe to send in a JSON response.
   * Stack traces are intentionally excluded from the public payload.
   *
   * @returns {{ error: { code: string, message: string, statusCode: number } }}
   */
  toJSON() {
    return {
      error: {
        code:       this.code,
        message:    this.message,
        statusCode: this.statusCode,
      },
    };
  }
}

// ─── 404 Not Found ────────────────────────────────────────────────────────────

/**
 * Thrown when a requested resource cannot be located.
 *
 * HTTP 404 Not Found
 *
 * @example
 *   throw new NotFoundError('User not found', 'USER_NOT_FOUND');
 *   throw new NotFoundError(`Order ${id} does not exist`);
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message='Resource not found']
   * @param {string} [code='NOT_FOUND']
   */
  constructor(message = 'Resource not found', code = 'NOT_FOUND') {
    super(message, 404, code);
  }
}

// ─── 422 Validation Error ─────────────────────────────────────────────────────

/**
 * Thrown when incoming request data fails validation rules.
 * Optionally carries a `fields` map of per-field error messages so that API
 * consumers can surface precise feedback to end-users.
 *
 * HTTP 422 Unprocessable Entity
 *
 * @example
 *   throw new ValidationError('Email is required');
 *   throw new ValidationError('Invalid payload', 'INVALID_PAYLOAD', {
 *     email: 'must be a valid email address',
 *     age:   'must be a positive integer',
 *   });
 */
class ValidationError extends AppError {
  /**
   * @param {string}                  [message='Validation failed']
   * @param {string}                  [code='VALIDATION_ERROR']
   * @param {Record<string, string>}  [fields={}]  Per-field error details.
   */
  constructor(message = 'Validation failed', code = 'VALIDATION_ERROR', fields = {}) {
    super(message, 422, code);
    this.fields = fields;
  }

  /** @override – includes per-field detail when present. */
  toJSON() {
    const base = super.toJSON();
    if (Object.keys(this.fields).length > 0) {
      base.error.fields = this.fields;
    }
    return base;
  }
}

// ─── 503 Database Error ───────────────────────────────────────────────────────

/**
 * Thrown when a database operation fails in an unrecoverable way (connection
 * refused, query timeout, constraint violation that escapes validation, …).
 *
 * HTTP 503 Service Unavailable
 *
 * The original low-level `cause` is stored on the instance for server-side
 * logging but is never forwarded to the client.
 *
 * @example
 *   try {
 *     await db.query(sql);
 *   } catch (err) {
 *     throw new DatabaseError('Failed to fetch users', 'DB_QUERY_FAILED', err);
 *   }
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message='A database error occurred']
   * @param {string} [code='DATABASE_ERROR']
   * @param {Error}  [cause=null]  The original low-level error (never sent to client).
   */
  constructor(
    message = 'A database error occurred',
    code    = 'DATABASE_ERROR',
    cause   = null,
  ) {
    // DatabaseError is operational when it has a clear cause (e.g. a DB
    // connection blip).  Without a cause it may indicate a programmer mistake,
    // so we mark it as non-operational to trigger extra logging.
    super(message, 503, code, cause !== null);
    this.cause = cause;
  }
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

'use strict';

/**
 * app.js
 * Express application with centralised error handling.
 *
 * Error flow
 * ──────────
 *  Route / middleware
 *    └─ throws AppError (or subclass)   ← operational errors
 *    └─ calls next(err)                 ← any error from async handlers
 *    └─ throws unexpected Error         ← programmer / runtime errors
 *         ↓
 *  errorHandler middleware              ← single place that writes the response
 */

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

// ─── Body Parsing ─────────────────────────────────────────────────────────────

app.use(express.json());

// ─── Helper ──────────────────────────────────────────────────────────────────

/**
 * Wraps an async route handler so any rejected promise (or thrown error) is
 * automatically forwarded to Express's next(err) without needing a try/catch
 * in every handler.
 *
 * @param {Function} fn  Async route handler (req, res, next) => Promise
 * @returns {Function}   Standard Express route handler
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ─── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Simple liveness probe – always succeeds while the process is running.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns a static list of users.
 *
 * In a real application the database call would live here; any failure is
 * wrapped in a DatabaseError so the global handler can present a uniform
 * error shape to the client.
 */
app.get('/users', asyncHandler(async (req, res) => {
  // --- Simulated data layer -------------------------------------------------
  // Replace this block with a real DB query.  On failure, wrap the caught
  // error in a DatabaseError before re-throwing:
  //
  //   try {
  //     const users = await db.query('SELECT * FROM users');
  //     res.json(users);
  //   } catch (err) {
  //     throw new DatabaseError('Failed to fetch users', 'DB_QUERY_FAILED', err);
  //   }
  // -------------------------------------------------------------------------
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  res.json(users);
}));

/**
 * GET /users/:id
 * Returns a single user by numeric ID.
 *
 * Demonstrates:
 *   - ValidationError  for a non-numeric :id param
 *   - NotFoundError    when the user does not exist in the data layer
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const { id } = req.params;

  // Validate that the id segment is a positive integer before touching the DB.
  if (!/^\d+$/.test(id)) {
    throw new ValidationError(
      `User ID must be a positive integer, received: "${id}"`,
      'INVALID_USER_ID',
      { id: 'must be a positive integer' },
    );
  }

  const numericId = parseInt(id, 10);

  // --- Simulated data layer -------------------------------------------------
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  const user = users.find((u) => u.id === numericId);
  // -------------------------------------------------------------------------

  if (!user) {
    throw new NotFoundError(`User with ID ${numericId} not found`, 'USER_NOT_FOUND');
  }

  res.json(user);
}));

// ─── 404 Catch-All ────────────────────────────────────────────────────────────

/**
 * Matches any request that did not hit a defined route and converts it into a
 * NotFoundError so the central error handler can format it consistently.
 * Must be registered AFTER all real routes.
 */
app.use((req, res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.path} not found`, 'ROUTE_NOT_FOUND'));
});

// ─── Centralised Error Handler ────────────────────────────────────────────────

/**
 * Global error-handling middleware.
 *
 * Express identifies this as an error handler because it declares four
 * parameters (err, req, res, next).  It must be the LAST middleware registered.
 *
 * Responsibilities
 * ────────────────
 *  1. Normalise unknown errors into a safe AppError shape.
 *  2. Log non-operational errors with their full stack trace.
 *  3. Send a single, consistent JSON error payload to the client.
 *  4. Never leak internal details (stack traces, DB messages) to the client.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── 1. Normalise ──────────────────────────────────────────────────────────
  //
  // If the thrown value is already one of our AppError subclasses we can use
  // it directly.  Anything else (plain Error, library error, …) is wrapped in
  // a generic 500 so the response shape stays consistent.
  const isAppError = err instanceof AppError;

  const normalised = isAppError
    ? err
    : new AppError(
        'An unexpected internal error occurred',
        500,
        'INTERNAL_SERVER_ERROR',
        false,             // not operational — we didn't anticipate this
      );

  // ── 2. Logging ────────────────────────────────────────────────────────────
  //
  // Always log the *original* error (before normalisation) so nothing is lost.
  // Non-operational errors get the full stack; operational ones get a one-liner
  // to keep logs readable.
  if (!normalised.isOperational) {
    // Programmer / unexpected error — log everything, including the original.
    console.error('[ERROR] Unexpected error caught by global handler:');
    console.error(err);
  } else {
    // Expected operational error — a concise log line is enough.
    console.warn(
      `[WARN] Operational error: ${normalised.code} | ${normalised.statusCode} | ${normalised.message}`,
    );
  }

  // DatabaseError: also log the low-level cause so on-call engineers can
  // diagnose the root problem without exposing it to the client.
  if (err instanceof DatabaseError && err.cause) {
    console.error('[ERROR] Database error cause:', err.cause);
  }

  // ── 3. Response ───────────────────────────────────────────────────────────
  //
  // Use the normalised error's toJSON() which is guaranteed to omit stack
  // traces and internal fields.
  res.status(normalised.statusCode).json(normalised.toJSON());
});

// ─── Server Bootstrap ─────────────────────────────────────────────────────────

/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

