'use strict';

const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

let passed = 0;
let failed = 0;

function assert(label, condition) {
  if (condition) {
    console.log(`  ✓  ${label}`);
    passed++;
  } else {
    console.error(`  ✗  ${label}`);
    failed++;
  }
}

// ── AppError ────────────────────────────────────────────────────────────────
console.log('\nAppError');
const base = new AppError('boom', 500, 'BASE_ERR');
assert('instanceof Error',    base instanceof Error);
assert('instanceof AppError', base instanceof AppError);
assert('statusCode 500',      base.statusCode === 500);
assert('code set',            base.code === 'BASE_ERR');
assert('isOperational true',  base.isOperational === true);
assert('toJSON shape correct',
  JSON.stringify(base.toJSON()) ===
  JSON.stringify({ error: { code: 'BASE_ERR', message: 'boom', statusCode: 500 } })
);

// ── NotFoundError ────────────────────────────────────────────────────────────
console.log('\nNotFoundError');
const nfe = new NotFoundError('User not found', 'USER_NOT_FOUND');
assert('instanceof AppError',    nfe instanceof AppError);
assert('instanceof NotFoundError', nfe instanceof NotFoundError);
assert('statusCode 404',         nfe.statusCode === 404);
assert('code USER_NOT_FOUND',    nfe.code === 'USER_NOT_FOUND');
assert('isOperational true',     nfe.isOperational === true);
assert('default message works',  new NotFoundError().message === 'Resource not found');
assert('default code works',     new NotFoundError().code === 'NOT_FOUND');

// ── ValidationError ──────────────────────────────────────────────────────────
console.log('\nValidationError');
const ve = new ValidationError('Bad email', 'INVALID_EMAIL', { email: 'invalid format' });
assert('instanceof AppError',       ve instanceof AppError);
assert('instanceof ValidationError', ve instanceof ValidationError);
assert('statusCode 422',            ve.statusCode === 422);
assert('fields present in toJSON',  ve.toJSON().error.fields.email === 'invalid format');
const veNoFields = new ValidationError();
assert('no fields key when empty',  veNoFields.toJSON().error.fields === undefined);
assert('default message works',     veNoFields.message === 'Validation failed');

// ── DatabaseError ────────────────────────────────────────────────────────────
console.log('\nDatabaseError');
const cause = new Error('connection refused');
const dbe = new DatabaseError('DB is down', 'DB_CONN_FAILED', cause);
assert('instanceof AppError',    dbe instanceof AppError);
assert('instanceof DatabaseError', dbe instanceof DatabaseError);
assert('statusCode 503',         dbe.statusCode === 503);
assert('cause stored',           dbe.cause === cause);
assert('isOperational true (has cause)', dbe.isOperational === true);
const dbeNoCause = new DatabaseError();
assert('isOperational false (no cause)', dbeNoCause.isOperational === false);

// ── instanceof still works after throw/catch ─────────────────────────────────
console.log('\nPrototype chain after throw/catch');
try { throw new NotFoundError('x'); } catch (e) {
  assert('caught as NotFoundError', e instanceof NotFoundError);
  assert('caught as AppError',      e instanceof AppError);
  assert('caught as Error',         e instanceof Error);
}

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);
EOF

