'use strict';

const http = require('http');
const app  = require('./app');

const server = http.createServer(app);
server.listen(0);   // random free port

const PORT = server.address().port;

async function get(path) {
  return new Promise((resolve) => {
    http.get(`http://localhost:${PORT}${path}`, (res) => {
      let body = '';
      res.on('data', (c) => (body += c));
      res.on('end', () => resolve({ status: res.statusCode, body: JSON.parse(body) }));
    });
  });
}

let passed = 0;
let failed = 0;

function assert(label, condition) {
  if (condition) { console.log(`  ✓  ${label}`); passed++; }
  else           { console.error(`  ✗  ${label}`); failed++; }
}

(async () => {
  // GET /health ──────────────────────────────────────────────────────────────
  console.log('\nGET /health');
  const health = await get('/health');
  assert('status 200',           health.status === 200);
  assert('body.status is ok',    health.body.status === 'ok');
  assert('body has timestamp',   typeof health.body.timestamp === 'string');

  // GET /users ───────────────────────────────────────────────────────────────
  console.log('\nGET /users');
  const users = await get('/users');
  assert('status 200',           users.status === 200);
  assert('returns array',        Array.isArray(users.body));
  assert('two users',            users.body.length === 2);
  assert('first user is Alice',  users.body[0].name === 'Alice');

  // GET /users/:id  – found ──────────────────────────────────────────────────
  console.log('\nGET /users/1  (found)');
  const alice = await get('/users/1');
  assert('status 200',           alice.status === 200);
  assert('returns Alice',        alice.body.name === 'Alice');

  // GET /users/:id  – not found ─────────────────────────────────────────────
  console.log('\nGET /users/99  (not found)');
  const missing = await get('/users/99');
  assert('status 404',           missing.status === 404);
  assert('error.code set',       missing.body.error.code === 'USER_NOT_FOUND');
  assert('error.message set',    typeof missing.body.error.message === 'string');
  assert('no stack in body',     missing.body.error.stack === undefined);

  // GET /users/:id  – invalid id ────────────────────────────────────────────
  console.log('\nGET /users/abc  (validation error)');
  const badId = await get('/users/abc');
  assert('status 422',           badId.status === 422);
  assert('error.code set',       badId.body.error.code === 'INVALID_USER_ID');
  assert('fields.id present',    badId.body.error.fields.id !== undefined);

  // GET /nonexistent  – catch-all 404 ───────────────────────────────────────
  console.log('\nGET /nonexistent  (route not found)');
  const noRoute = await get('/nonexistent');
  assert('status 404',           noRoute.status === 404);
  assert('error.code ROUTE_NOT_FOUND', noRoute.body.error.code === 'ROUTE_NOT_FOUND');

  console.log(`\n${passed} passed, ${failed} failed`);
  server.close();
  process.exit(failed > 0 ? 1 : 0);
})();
