/**
 * errors.js
 *
 * Centralised custom error classes for the Express application.
 * Every class extends the built-in Error and carries:
 *   - message   – human-readable description
 *   - statusCode – HTTP status code sent to the client
 *   - code       – machine-readable error identifier (useful for clients / logging)
 *   - isOperational – marks errors that are "expected" (user/input mistakes) vs
 *                     programmer bugs; the global handler uses this flag to decide
 *                     whether to expose detail to the caller.
 */

'use strict';

// ─── Base ────────────────────────────────────────────────────────────────────

class AppError extends Error {
  /**
   * @param {string}  message        - Human-readable description.
   * @param {number}  statusCode     - HTTP status code (default 500).
   * @param {string}  code           - Machine-readable identifier.
   * @param {boolean} isOperational  - true = expected error, false = programmer bug.
   */
  constructor(
    message,
    statusCode = 500,
    code = 'INTERNAL_ERROR',
    isOperational = true,
  ) {
    super(message);

    // Restore the correct constructor name so stack-traces read clearly.
    this.name = this.constructor.name;
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;

    // Capture a clean stack-trace that omits this constructor frame.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ─── Concrete error classes ───────────────────────────────────────────────────

/**
 * 404 Not Found
 * Thrown when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User not found', 'USER_NOT_FOUND');
 */
class NotFoundError extends AppError {
  /**
   * @param {string} message - Defaults to 'Resource not found'.
   * @param {string} code    - Defaults to 'NOT_FOUND'.
   */
  constructor(message = 'Resource not found', code = 'NOT_FOUND') {
    super(message, 404, code, true);
  }
}

/**
 * 422 Unprocessable Entity
 * Thrown when client-supplied data fails validation rules.
 *
 * @example
 *   throw new ValidationError('Email is required', 'MISSING_EMAIL');
 *   throw new ValidationError('Invalid payload', 'INVALID_PAYLOAD', { fields: ['email'] });
 */
class ValidationError extends AppError {
  /**
   * @param {string} message - Defaults to 'Validation failed'.
   * @param {string} code    - Defaults to 'VALIDATION_ERROR'.
   * @param {object} details - Optional field-level details to forward to the client.
   */
  constructor(
    message = 'Validation failed',
    code = 'VALIDATION_ERROR',
    details = null,
  ) {
    super(message, 422, code, true);
    // Extra context (e.g. which fields failed) surfaced in the error response.
    this.details = details;
  }
}

/**
 * 503 Service Unavailable
 * Thrown when a database / storage operation fails.
 *
 * isOperational is set to false by default because a database failure is
 * generally not something the caller can resolve — the server itself is in a
 * degraded state. The global handler will therefore hide implementation details
 * and return a generic "service unavailable" message.
 *
 * Set isOperational = true if you want to surface the message to the client
 * (e.g. a predictable "record not found" from your ORM that you want to treat
 * as a 503 rather than a 404).
 *
 * @example
 *   throw new DatabaseError('Connection pool exhausted', 'DB_POOL_EXHAUSTED');
 */
class DatabaseError extends AppError {
  /**
   * @param {string}  message        - Defaults to 'Database operation failed'.
   * @param {string}  code           - Defaults to 'DATABASE_ERROR'.
   * @param {boolean} isOperational  - Defaults to false (hide internals from client).
   */
  constructor(
    message = 'Database operation failed',
    code = 'DATABASE_ERROR',
    isOperational = false,
  ) {
    super(message, 503, code, isOperational);
  }
}

// ─── Exports ─────────────────────────────────────────────────────────────────

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

'use strict';

/**
 * app.js
 *
 * Express application with centralised error handling.
 *
 * Error-handling flow
 * ───────────────────
 *  1. Routes throw an AppError subclass (NotFoundError, ValidationError,
 *     DatabaseError) instead of calling res.status().json() inline.
 *  2. Async route helpers are wrapped with asyncHandler() so that any thrown
 *     error (or rejected promise) is automatically forwarded to next(err).
 *  3. An explicit 404 catch-all fires after all routes to handle unknown paths.
 *  4. The single 4-argument errorHandler middleware at the bottom serialises
 *     every error into a consistent JSON envelope and picks the right HTTP
 *     status code.
 */

const express = require('express');
const { NotFoundError, ValidationError, DatabaseError, AppError } = require('./errors');

const app = express();
app.use(express.json());

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Wraps an async route handler so that any thrown error or rejected promise is
 * forwarded to Express's next(err) without needing try/catch in every route.
 *
 * @param   {Function} fn - Async (req, res, next) handler.
 * @returns {Function}    Standard Express middleware.
 */
const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

// ─── In-memory data store (stand-in for a real DB) ────────────────────────────

let users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// Simple auto-increment helper — keeps the demo self-contained.
const nextId = () => (users.length > 0 ? Math.max(...users.map((u) => u.id)) + 1 : 1);

// ─── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Basic liveness probe — never throws intentionally.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns the full list of users.
 *
 * Demonstrates DatabaseError: simulate a DB failure by passing ?fail=1.
 * e.g. GET /users?fail=1
 */
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // Simulated transient database error path (for testing purposes only).
    if (req.query.fail === '1') {
      throw new DatabaseError(
        'Could not reach the users table',
        'DB_USERS_UNAVAILABLE',
      );
    }

    res.json(users);
  }),
);

/**
 * GET /users/:id
 * Returns a single user by numeric ID.
 * Throws NotFoundError when the ID is not present in the store.
 */
app.get(
  '/users/:id',
  asyncHandler(async (req, res) => {
    const id = Number(req.params.id);

    if (!Number.isInteger(id) || id <= 0) {
      throw new ValidationError(
        `'${req.params.id}' is not a valid user ID`,
        'INVALID_USER_ID',
      );
    }

    const user = users.find((u) => u.id === id);

    if (!user) {
      throw new NotFoundError(`User with ID ${id} not found`, 'USER_NOT_FOUND');
    }

    res.json(user);
  }),
);

/**
 * POST /users
 * Creates a new user.
 * Throws ValidationError when required fields are absent or malformed.
 *
 * Expected body: { name: string, email: string }
 */
app.post(
  '/users',
  asyncHandler(async (req, res) => {
    const { name, email } = req.body ?? {};
    const missingFields = [];

    if (!name  || typeof name  !== 'string' || !name.trim())  missingFields.push('name');
    if (!email || typeof email !== 'string' || !email.trim()) missingFields.push('email');

    if (missingFields.length > 0) {
      throw new ValidationError(
        `Missing required field(s): ${missingFields.join(', ')}`,
        'MISSING_REQUIRED_FIELDS',
        { missingFields },
      );
    }

    // Rudimentary e-mail format guard.
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) {
      throw new ValidationError(
        `'${email}' is not a valid email address`,
        'INVALID_EMAIL_FORMAT',
        { fields: ['email'] },
      );
    }

    // Uniqueness check (mirrors what a real DB constraint would raise).
    if (users.some((u) => u.email.toLowerCase() === email.trim().toLowerCase())) {
      throw new ValidationError(
        `A user with email '${email.trim()}' already exists`,
        'DUPLICATE_EMAIL',
        { fields: ['email'] },
      );
    }

    const newUser = { id: nextId(), name: name.trim(), email: email.trim() };
    users.push(newUser);

    res.status(201).json(newUser);
  }),
);

/**
 * PUT /users/:id
 * Replaces a user's name and/or email.
 * Throws NotFoundError or ValidationError as appropriate.
 */
app.put(
  '/users/:id',
  asyncHandler(async (req, res) => {
    const id = Number(req.params.id);

    if (!Number.isInteger(id) || id <= 0) {
      throw new ValidationError(
        `'${req.params.id}' is not a valid user ID`,
        'INVALID_USER_ID',
      );
    }

    const index = users.findIndex((u) => u.id === id);

    if (index === -1) {
      throw new NotFoundError(`User with ID ${id} not found`, 'USER_NOT_FOUND');
    }

    const { name, email } = req.body ?? {};

    // At least one field must be supplied.
    if (!name && !email) {
      throw new ValidationError(
        'Request body must include at least one of: name, email',
        'EMPTY_UPDATE_PAYLOAD',
      );
    }

    if (email !== undefined) {
      if (typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) {
        throw new ValidationError(
          `'${email}' is not a valid email address`,
          'INVALID_EMAIL_FORMAT',
          { fields: ['email'] },
        );
      }

      // Uniqueness check — allow the user to keep their own e-mail.
      const duplicate = users.find(
        (u) => u.id !== id && u.email.toLowerCase() === email.trim().toLowerCase(),
      );
      if (duplicate) {
        throw new ValidationError(
          `A user with email '${email.trim()}' already exists`,
          'DUPLICATE_EMAIL',
          { fields: ['email'] },
        );
      }
    }

    users[index] = {
      ...users[index],
      ...(name  ? { name:  name.trim()  } : {}),
      ...(email ? { email: email.trim() } : {}),
    };

    res.json(users[index]);
  }),
);

/**
 * DELETE /users/:id
 * Removes a user from the store.
 * Throws NotFoundError when the ID does not exist.
 */
app.delete(
  '/users/:id',
  asyncHandler(async (req, res) => {
    const id = Number(req.params.id);

    if (!Number.isInteger(id) || id <= 0) {
      throw new ValidationError(
        `'${req.params.id}' is not a valid user ID`,
        'INVALID_USER_ID',
      );
    }

    const index = users.findIndex((u) => u.id === id);

    if (index === -1) {
      throw new NotFoundError(`User with ID ${id} not found`, 'USER_NOT_FOUND');
    }

    users.splice(index, 1);
    res.status(204).send();
  }),
);

// ─── 404 catch-all ────────────────────────────────────────────────────────────

/**
 * Fires for every request that did not match a route above.
 * Delegates to the central error handler via next(err).
 */
app.use((req, res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.path} not found`, 'ROUTE_NOT_FOUND'));
});

// ─── Centralised error-handling middleware ────────────────────────────────────

/**
 * Global error handler — must be defined with exactly 4 parameters so that
 * Express recognises it as an error-handling middleware.
 *
 * Response envelope
 * ─────────────────
 * {
 *   "error": {
 *     "code":       "MACHINE_READABLE_CODE",
 *     "message":    "Human-readable description",
 *     "details":    { ... } | null,   // only for ValidationError
 *     "stack":      "..."             // only in development
 *   }
 * }
 *
 * Operational vs non-operational
 * ───────────────────────────────
 * - Operational (isOperational: true):  the error message is safe to forward to
 *   the client (e.g. "User not found", "Email is required").
 * - Non-operational (isOperational: false):  something unexpected happened
 *   (database crash, unhandled programmer bug). We log the full error internally
 *   and return a generic 500 / 503 message so implementation details are never
 *   leaked.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── Normalise unknown/unexpected errors ──────────────────────────────────
  const isAppError = err instanceof AppError;

  const statusCode     = isAppError ? err.statusCode    : 500;
  const code           = isAppError ? err.code          : 'INTERNAL_ERROR';
  const isOperational  = isAppError ? err.isOperational : false;

  // ── Logging ──────────────────────────────────────────────────────────────
  // Non-operational errors are always logged at error level; operational ones
  // only at warn so that routine 404s don't flood production logs.
  if (!isOperational) {
    console.error('[ERROR]', {
      code,
      message:    err.message,
      stack:      err.stack,
      path:       req.path,
      method:     req.method,
    });
  } else {
    console.warn('[WARN]', { code, message: err.message, path: req.path, method: req.method });
  }

  // ── Build response ───────────────────────────────────────────────────────
  const responseBody = {
    error: {
      code,
      // Hide internal details for non-operational errors in production.
      message: isOperational
        ? err.message
        : 'An unexpected error occurred. Please try again later.',
      // Surface field-level detail only for ValidationError instances.
      ...(err.details != null && { details: err.details }),
      // Attach stack trace in development to ease debugging.
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
    },
  };

  res.status(statusCode).json(responseBody);
});

// ─── Server bootstrap ─────────────────────────────────────────────────────────

/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT ?? 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

