console.assert(ve instanceof AppError,   'ValidationError extends AppError');
console.assert(ve.statusCode === 422,    'ValidationError statusCode is 422');
console.assert(ve.isOperational === true,'ValidationError isOperational true');
console.assert(ve.details.fields[0] === 'email', 'ValidationError details forwarded');
console.log('ValidationError: PASS');

// ── DatabaseError ─────────────────────────────────────
const de = new DatabaseError();
console.assert(de instanceof AppError,    'DatabaseError extends AppError');
console.assert(de.statusCode === 503,     'DatabaseError statusCode is 503');
console.assert(de.isOperational === false,'DatabaseError isOperational false (default)');
console.log('DatabaseError: PASS');

// ── Defaults ──────────────────────────────────────────
const nfeDef = new NotFoundError();
console.assert(nfeDef.message === 'Resource not found', 'NotFoundError default message');
const veDef  = new ValidationError();
console.assert(veDef.message  === 'Validation failed',  'ValidationError default message');
const deDef  = new DatabaseError();
console.assert(deDef.message  === 'Database operation failed', 'DatabaseError default message');
console.log('Defaults: PASS');

// ── Stack trace populated ────────────────────────────────────
console.assert(typeof nfe.stack === 'string' && nfe.stack.length > 0, 'Stack trace present');
console.log('Stack trace: PASS');
