/**
 * errors.js
 * ---------
 * Central catalogue of application-level error classes.
 *
 * Every class extends the built-in Error and carries:
 *   - message   – human-readable description (inherited from Error)
 *   - statusCode – the HTTP status code the error maps to
 *   - code       – a stable machine-readable identifier for clients
 *   - isOperational – true  → expected/handled error (log at warn level)
 *                     false → programming bug   (log at error level, alert)
 *
 * Usage (inside a route or service):
 *
 *   const { NotFoundError, ValidationError, DatabaseError } = require('./errors');
 *
 *   throw new NotFoundError('User not found');
 *   throw new ValidationError('Email is required', { field: 'email' });
 *   throw new DatabaseError('Query timed out');
 */

'use strict';

// ─── Base ────────────────────────────────────────────────────────────────────

class AppError extends Error {
  /**
   * @param {string}  message        - Human-readable error description.
   * @param {number}  statusCode     - HTTP status code (e.g. 404, 422, 500).
   * @param {string}  code           - Machine-readable error code.
   * @param {boolean} isOperational  - Whether this is an expected runtime error.
   * @param {object}  [details]      - Optional extra context (field names, etc.).
   */
  constructor(message, statusCode, code, isOperational = true, details = null) {
    super(message);

    // Maintain the correct prototype chain so `instanceof` checks work after
    // TypeScript / Babel transpilation as well as plain Node.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.code        = code;
    this.isOperational = isOperational;

    // Optional structured detail payload (e.g. validation field errors).
    if (details !== null && details !== undefined) {
      this.details = details;
    }

    // Capture a clean stack trace that starts at the throw site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ─── 404 Not Found ───────────────────────────────────────────────────────────

/**
 * Thrown when a requested resource does not exist.
 *
 * HTTP 404 Not Found
 *
 * @example
 *   throw new NotFoundError('User not found');
 *   throw new NotFoundError(`Order ${id} not found`);
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message] - Defaults to 'Resource not found'.
   * @param {object} [details] - Optional extra context.
   */
  constructor(message = 'Resource not found', details = null) {
    super(message, 404, 'NOT_FOUND', true, details);
  }
}

// ─── 422 Validation Error ────────────────────────────────────────────────────

/**
 * Thrown when request input fails validation rules.
 *
 * HTTP 422 Unprocessable Entity
 *
 * The optional `details` field is intended for structured per-field error
 * information that clients can map back to form fields:
 *
 *   { field: 'email', reason: 'must be a valid email address' }
 *
 * @example
 *   throw new ValidationError('Email is required');
 *   throw new ValidationError('Invalid input', { field: 'email', reason: 'required' });
 */
class ValidationError extends AppError {
  /**
   * @param {string} [message] - Defaults to 'Validation failed'.
   * @param {object} [details] - Optional structured field-level info.
   */
  constructor(message = 'Validation failed', details = null) {
    super(message, 422, 'VALIDATION_ERROR', true, details);
  }
}

// ─── 503 Database Error ──────────────────────────────────────────────────────

/**
 * Thrown when a database operation fails (connection error, query failure,
 * constraint violation that is not already caught as a ValidationError, etc.).
 *
 * HTTP 503 Service Unavailable
 *
 * Marked as NOT operational (isOperational = false) by default because a DB
 * failure is almost always unexpected in production and should trigger an alert.
 * Pass `true` as the second argument for expected, transient failures
 * (e.g. a read-replica lag retry) where you do NOT want an alert fired.
 *
 * @example
 *   throw new DatabaseError('Connection pool exhausted');
 *   throw new DatabaseError('Read replica unavailable – retrying', true);
 */
class DatabaseError extends AppError {
  /**
   * @param {string}  [message]       - Defaults to 'A database error occurred'.
   * @param {boolean} [isOperational] - Defaults to false (triggers alerts).
   * @param {object}  [details]       - Optional extra context.
   */
  constructor(
    message = 'A database error occurred',
    isOperational = false,
    details = null,
  ) {
    super(message, 503, 'DATABASE_ERROR', isOperational, details);
  }
}

// ─── Exports ─────────────────────────────────────────────────────────────────

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

/**
 * app.js
 * ------
 * Express application entry-point.
 *
 * Error-handling strategy
 * ───────────────────────
 * Routes NEVER call res.status().json() for error cases directly.
 * Instead they throw (sync) or call next(err) (async) with one of the
 * typed error classes from ./errors.js.
 *
 * Two middleware pieces at the bottom of the file catch everything:
 *
 *   1. 404 catch-all  – converts unmatched routes into NotFoundErrors.
 *   2. errorHandler   – the single place that serialises every AppError
 *                       (and unexpected Error) into a JSON response.
 */

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

app.use(express.json());

// ─── In-memory data store (demo) ─────────────────────────────────────────────

const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Simulate a (potentially failing) database lookup by user id.
 * Returns the user object or throws a typed error.
 *
 * @param {number} id
 * @returns {{ id: number, name: string, email: string }}
 */
function findUserById(id) {
  // Guard: id must be a positive integer.
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('User id must be a positive integer', {
      field: 'id',
      reason: 'must be a positive integer',
    });
  }

  const user = USERS.find((u) => u.id === id);
  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`);
  }

  return user;
}

/**
 * Validate the fields required to create a new user.
 *
 * @param {{ name?: unknown, email?: unknown }} body
 */
function validateNewUser(body) {
  if (!body || typeof body !== 'object') {
    throw new ValidationError('Request body must be a JSON object');
  }

  const errors = [];

  if (!body.name || typeof body.name !== 'string' || body.name.trim() === '') {
    errors.push({ field: 'name', reason: 'required and must be a non-empty string' });
  }

  if (!body.email || typeof body.email !== 'string' || !body.email.includes('@')) {
    errors.push({ field: 'email', reason: 'required and must be a valid email address' });
  }

  if (errors.length > 0) {
    throw new ValidationError('Invalid user payload', { fields: errors });
  }
}

// ─── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Simple liveness probe – never throws.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Return the full list of users.
 *
 * Demonstrates: DatabaseError thrown from the data layer bubbling up
 * through the centralised error handler.
 */
app.get('/users', (req, res) => {
  // Simulate an unexpected DB outage via query param for demo purposes.
  // e.g. GET /users?simulateDbError=1
  if (req.query.simulateDbError) {
    throw new DatabaseError('Connection to primary replica lost');
  }

  res.json(USERS);
});

/**
 * GET /users/:id
 * Return a single user by numeric id.
 *
 * Demonstrates: NotFoundError and ValidationError thrown from a helper.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);
  // findUserById throws NotFoundError or ValidationError – both bubble to
  // the central error handler automatically.
  const user = findUserById(id);
  res.json(user);
});

/**
 * POST /users
 * Create a new user.
 *
 * Demonstrates: ValidationError thrown from validateNewUser, plus an explicit
 * DatabaseError for a simulated write failure.
 */
app.post('/users', (req, res) => {
  // Throws ValidationError when input is invalid.
  validateNewUser(req.body);

  // Simulate an unexpected DB write failure via body flag.
  if (req.body.simulateDbError) {
    throw new DatabaseError('Write to users table failed');
  }

  const newUser = {
    id:    USERS.length + 1,
    name:  req.body.name.trim(),
    email: req.body.email.trim(),
  };

  USERS.push(newUser);
  res.status(201).json(newUser);
});

// ─── 404 catch-all ────────────────────────────────────────────────────────────

/**
 * Convert any request that reaches this point (no route matched) into a
 * typed NotFoundError so the single error handler can process it uniformly.
 *
 * IMPORTANT: this must be registered AFTER all routes.
 */
app.use((req, res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`));
});

// ─── Centralised error-handling middleware ────────────────────────────────────

/**
 * Single error handler for the entire application.
 *
 * Express identifies error-handling middleware by its four-argument signature
 * (err, req, res, next) – do not remove `next` even if it is unused.
 *
 * Responsibilities
 * ────────────────
 *  1. Distinguish operational AppErrors from unexpected programming errors.
 *  2. Log accordingly (warn vs error).
 *  3. Send a consistent JSON error envelope to the client.
 *  4. Never leak internal stack traces to the client in production.
 *
 * Response envelope
 * ─────────────────
 *  {
 *    "error": {
 *      "code":    "NOT_FOUND",          // machine-readable, stable
 *      "message": "User not found",     // human-readable
 *      "details": { ... }               // optional, present when set on the error
 *    }
 *  }
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── 1. Decide whether this is a known operational error ───────────────────
  const isAppError = err instanceof AppError;

  const statusCode = isAppError ? err.statusCode : 500;
  const code       = isAppError ? err.code       : 'INTERNAL_SERVER_ERROR';
  const message    = isAppError && err.isOperational
    ? err.message
    : 'An unexpected error occurred';

  // ── 2. Log ────────────────────────────────────────────────────────────────
  if (isAppError && err.isOperational) {
    // Expected runtime errors: warn level, no stack trace needed in prod.
    console.warn(`[${code}] ${err.message}`, err.details ?? '');
  } else {
    // Unexpected errors: full stack trace, should trigger an alert.
    console.error(`[UNHANDLED ERROR] ${err.message}\n`, err.stack);
  }

  // ── 3. Build response envelope ────────────────────────────────────────────
  const body = {
    error: {
      code,
      message,
    },
  };

  // Attach structured details only when they exist and are operational.
  // Never expose details from unknown errors (could contain stack / SQL / etc.)
  if (isAppError && err.isOperational && err.details) {
    body.error.details = err.details;
  }

  // Attach the stack trace in non-production environments to aid debugging.
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    body.error.stack = err.stack;
  }

  // ── 4. Send ───────────────────────────────────────────────────────────────
  res.status(statusCode).json(body);
});

// ─── Start ────────────────────────────────────────────────────────────────────

/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

