/**
 * errors.js
 * ─────────────────────────────────────────────────────────────────────────────
 * Centralised error classes for the Express application.
 *
 * All classes extend AppError, which itself extends the native Error so that:
 *   • instanceof checks work correctly throughout the stack.
 *   • Every error carries a stable HTTP statusCode and a machine-readable
 *     code string that clients can branch on without parsing messages.
 *   • The built-in Error.captureStackTrace call keeps stack traces clean by
 *     removing the constructor frames.
 *
 * Usage
 * ─────
 *   import / require the specific class you need in a route or service, then
 *   simply `throw new NotFoundError(...)`.  The centralised error-handling
 *   middleware in app.js will catch it and format the response automatically.
 *
 * Hierarchy
 * ─────────
 *   Error
 *   └── AppError          (base – never thrown directly)
 *       ├── NotFoundError     404  NOT_FOUND
 *       ├── ValidationError   422  VALIDATION_ERROR
 *       └── DatabaseError     503  DATABASE_ERROR
 */

'use strict';

// ─── Base error ──────────────────────────────────────────────────────────────

/**
 * AppError – base class for all application-level errors.
 *
 * @param {string}  message         Human-readable description of the error.
 * @param {number}  statusCode      HTTP status code to send to the client.
 * @param {string}  code            Machine-readable error code (SCREAMING_SNAKE).
 * @param {boolean} [isOperational] True for expected runtime errors (default),
 *                                  false for programming / unexpected errors.
 */
class AppError extends Error {
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Maintain correct prototype chain for `instanceof` checks.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = new.target.name; // e.g. "NotFoundError"
    this.statusCode  = statusCode;
    this.code        = code;
    this.isOperational = isOperational;
    this.timestamp   = new Date().toISOString();

    // Remove constructor frames from the stack trace for cleaner logs.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, new.target);
    }
  }

  /**
   * Serialise the error into a plain object safe for JSON responses.
   * Sensitive internals (stack, isOperational) are intentionally omitted.
   */
  toJSON() {
    return {
      error: {
        name:      this.name,
        code:      this.code,
        message:   this.message,
        timestamp: this.timestamp,
      },
    };
  }
}

// ─── 404 Not Found ───────────────────────────────────────────────────────────

/**
 * NotFoundError – thrown when a requested resource cannot be located.
 *
 * HTTP 404 Not Found
 *
 * @param {string} [resource]  Optional name of the missing resource, e.g. "User".
 * @param {string} [message]   Override the default message if needed.
 *
 * @example
 *   throw new NotFoundError('User');
 *   // → { error: { code: 'NOT_FOUND', message: 'User not found.' } }
 *
 *   throw new NotFoundError(null, 'The requested page does not exist.');
 */
class NotFoundError extends AppError {
  constructor(resource = null, message = null) {
    const defaultMessage = resource
      ? `${resource} not found.`
      : 'The requested resource was not found.';

    super(message || defaultMessage, 404, 'NOT_FOUND');
    this.resource = resource;
  }
}

// ─── 422 Validation Error ─────────────────────────────────────────────────────

/**
 * ValidationError – thrown when incoming data fails validation rules.
 *
 * HTTP 422 Unprocessable Entity
 *
 * @param {string}        [message] Override the default message if needed.
 * @param {Array<Object>} [fields]  Per-field validation failures.
 *                                  Each entry: { field, message, value? }
 *
 * @example
 *   throw new ValidationError('Invalid request body.', [
 *     { field: 'email', message: 'Must be a valid email address.' },
 *     { field: 'age',   message: 'Must be a positive integer.', value: -1 },
 *   ]);
 */
class ValidationError extends AppError {
  constructor(message = 'Validation failed.', fields = []) {
    super(message, 422, 'VALIDATION_ERROR');
    this.fields = fields; // Array<{ field, message, value? }>
  }

  /** Include the per-field details in the JSON payload. */
  toJSON() {
    const base = super.toJSON();
    if (this.fields.length > 0) {
      base.error.fields = this.fields;
    }
    return base;
  }
}

// ─── 503 Database Error ───────────────────────────────────────────────────────

/**
 * DatabaseError – thrown when a storage / persistence operation fails.
 *
 * HTTP 503 Service Unavailable  (the DB layer is treated as an upstream
 * dependency; 503 signals the client that retrying later may succeed).
 *
 * @param {string} [message]       Override the default message.
 * @param {Error}  [originalError] The underlying driver / ORM error.
 *                                 Stored for server-side logging but never
 *                                 forwarded to the client.
 *
 * @example
 *   try {
 *     await db.query(...);
 *   } catch (err) {
 *     throw new DatabaseError('Failed to fetch users.', err);
 *   }
 */
class DatabaseError extends AppError {
  constructor(message = 'A database error occurred.', originalError = null) {
    // DatabaseError is *operational* from a routing perspective (we know how to
    // handle it) but the root cause is unexpected, so isOperational = false
    // signals the error handler to log it with higher severity.
    super(message, 503, 'DATABASE_ERROR', false);
    this.originalError = originalError; // kept server-side only
  }

  /** Never expose originalError / internals to the client. */
  toJSON() {
    return super.toJSON(); // only the safe base fields
  }
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

/**
 * app.js
 * ─────────────────────────────────────────────────────────────────────────────
 * Express application.
 *
 * Error-handling strategy
 * ───────────────────────
 * Routes no longer call res.status().json() directly for error cases.
 * Instead they `throw` (sync routes) or call `next(err)` (async routes) with
 * one of the typed error classes from errors.js.  A single centralised
 * error-handling middleware at the bottom of the file is the only place that
 * translates errors into HTTP responses, ensuring:
 *
 *   • Consistent response shape across every endpoint.
 *   • A clean separation between business logic and HTTP concerns.
 *   • One place to update logging, alerting, or response formatting.
 */

'use strict';

const express = require('express');

const {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
} = require('./errors');

const app = express();

// ─── Body parsing ─────────────────────────────────────────────────────────────

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// ─── In-memory data store (stand-in for a real DB layer) ─────────────────────

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ─── Helper: wrap async route handlers ───────────────────────────────────────

/**
 * asyncHandler
 * Wraps an async route handler so that any rejected promise or thrown error is
 * forwarded to Express's next(err) automatically.  Without this wrapper, async
 * errors are silently swallowed by Express 4.
 *
 * @param  {Function} fn  Async (req, res, next) handler.
 * @returns {Function}    Standard Express middleware.
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ─── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Simple liveness probe – always succeeds if the process is running.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ── Users ─────────────────────────────────────────────────────────────────────

/**
 * GET /users
 * Returns the full list of users.
 *
 * Simulates a database read; throws DatabaseError when the store is
 * unavailable instead of leaking raw driver errors to the client.
 */
app.get('/users', asyncHandler(async (req, res) => {
  // Simulate a DB call.  In a real app: await db.user.findMany()
  if (!users) {
    throw new DatabaseError('Failed to retrieve users from the database.');
  }

  res.json(users);
}));

/**
 * GET /users/:id
 * Returns a single user by numeric ID.
 *
 * Throws:
 *   ValidationError  – if :id is not a positive integer.
 *   NotFoundError    – if no user with that ID exists.
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const id = Number(req.params.id);

  // Validate: id must be a finite, positive integer.
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Invalid user ID.', [
      {
        field:   'id',
        message: 'Must be a positive integer.',
        value:   req.params.id,
      },
    ]);
  }

  // Simulate a DB lookup.  In a real app: await db.user.findUnique({ where: { id } })
  const user = users.find((u) => u.id === id);

  if (!user) {
    throw new NotFoundError('User');
  }

  res.json(user);
}));

/**
 * POST /users
 * Creates a new user.
 *
 * Expected body: { name: string, email: string }
 *
 * Throws:
 *   ValidationError – if required fields are missing or malformed.
 *   DatabaseError   – if the simulated persistence layer fails.
 */
app.post('/users', asyncHandler(async (req, res) => {
  const { name, email } = req.body;

  // Collect all field-level failures before throwing so the client gets
  // everything wrong in one round-trip.
  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'Name is required and must be a non-empty string.' });
  }

  if (!email || typeof email !== 'string' || email.trim() === '') {
    fieldErrors.push({ field: 'email', message: 'Email is required and must be a non-empty string.' });
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) {
    fieldErrors.push({ field: 'email', message: 'Must be a valid email address.', value: email });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Invalid request body.', fieldErrors);
  }

  // Check for duplicate email.
  const duplicate = users.find(
    (u) => u.email.toLowerCase() === email.trim().toLowerCase(),
  );
  if (duplicate) {
    throw new ValidationError('A user with this email already exists.', [
      { field: 'email', message: 'Email address is already in use.', value: email },
    ]);
  }

  // Simulate persistence.  In a real app: await db.user.create({ data: { name, email } })
  const newUser = {
    id:    users.length + 1,
    name:  name.trim(),
    email: email.trim().toLowerCase(),
  };

  try {
    users.push(newUser); // stand-in for an async DB write
  } catch (err) {
    throw new DatabaseError('Failed to create user.', err);
  }

  res.status(201).json(newUser);
}));

/**
 * DELETE /users/:id
 * Removes a user by numeric ID.
 *
 * Throws:
 *   ValidationError – if :id is not a positive integer.
 *   NotFoundError   – if no user with that ID exists.
 *   DatabaseError   – if the simulated delete operation fails.
 */
app.delete('/users/:id', asyncHandler(async (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Invalid user ID.', [
      {
        field:   'id',
        message: 'Must be a positive integer.',
        value:   req.params.id,
      },
    ]);
  }

  const index = users.findIndex((u) => u.id === id);

  if (index === -1) {
    throw new NotFoundError('User');
  }

  try {
    users.splice(index, 1); // stand-in for an async DB delete
  } catch (err) {
    throw new DatabaseError('Failed to delete user.', err);
  }

  res.status(204).send();
}));

// ─── 404 catch-all (must come after all valid routes) ────────────────────────

/**
 * Any request that reaches this point did not match a defined route.
 * We create a NotFoundError and pass it to the centralised error handler.
 */
app.use((req, _res, next) => {
  next(new NotFoundError(null, `Route ${req.method} ${req.originalUrl} not found.`));
});

// ─── Centralised error-handling middleware ────────────────────────────────────

/**
 * errorHandler
 *
 * This is the *single* place in the application that converts an error into an
 * HTTP response.  Express identifies it as an error handler because it declares
 * four parameters (err, req, res, next).
 *
 * Behaviour
 * ─────────
 *  • AppError subclasses  → use their own statusCode / toJSON() output.
 *  • SyntaxError from JSON body-parser → mapped to 400 Bad Request.
 *  • Everything else      → 500 Internal Server Error (details hidden from client).
 *
 * Logging
 * ───────
 *  • Operational errors (expected, e.g. NotFoundError) are logged at the
 *    'warn' level so they don't inflate error-rate alerts.
 *  • Non-operational / unexpected errors are logged at the 'error' level
 *    with the full stack trace so they are easy to debug.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── 1. Normalise the error into an AppError ──────────────────────────────

  let appError;

  if (err instanceof AppError) {
    // Already one of our typed errors – use as-is.
    appError = err;
  } else if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    // express.json() throws a SyntaxError for malformed JSON bodies.
    appError = new ValidationError('Malformed JSON in request body.', [
      { field: 'body', message: err.message },
    ]);
  } else {
    // Unknown / unexpected error – wrap in a generic 500 AppError and hide
    // internal details from the client.
    appError = new AppError(
      'An unexpected internal server error occurred.',
      500,
      'INTERNAL_SERVER_ERROR',
      false, // not operational
    );
    appError.originalError = err; // stash for server-side logging only
  }

  // ── 2. Log ───────────────────────────────────────────────────────────────

  const logContext = {
    method:     req.method,
    url:        req.originalUrl,
    statusCode: appError.statusCode,
    errorCode:  appError.code,
    stack:      appError.stack,
  };

  if (appError.isOperational) {
    // Expected operational error (404, 422, …) – log at warn level.
    console.warn('[warn] Operational error:', logContext);
  } else {
    // Unexpected / programming error – log the root cause too.
    if (appError.originalError) {
      logContext.originalError = appError.originalError.stack || appError.originalError.message;
    }
    console.error('[error] Unexpected error:', logContext);
  }

  // ── 3. Respond ───────────────────────────────────────────────────────────

  // Guard against trying to set headers after they have already been sent
  // (e.g. an error thrown inside a streaming response).
  if (res.headersSent) {
    return next(err);
  }

  res.status(appError.statusCode).json(appError.toJSON());
});

// ─── Start server (only when run directly, not during tests) ─────────────────

if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

