'use strict';
// ── Minimal Express mock ──────────────────────────────────────────────────────
// Replicates the subset of the Express API that app.js uses so we can run a
// complete integration smoke-test without a network / npm install.

const EventEmitter = require('events');

function createMockExpress() {
  const middlewares = [];

  // Simulate req / res for a single call
  function buildReqRes(method, url, body = {}) {
    const req = {
      method, originalUrl: url,
      params: {},
      body,
    };
    const res = {
      _status: 200, _body: null, headersSent: false,
      status(code) { this._status = code; return this; },
      json(data)  { this._body = data; this.headersSent = true; return this; },
      send(data)  { this._body = data ?? null; this.headersSent = true; return this; },
    };
    return { req, res };
  }

  // Walk middleware chain for a given method+url
  async function dispatch(method, url, body) {
    const { req, res } = buildReqRes(method, url, body);
    let i = 0;

    // Extract :param placeholders into req.params
    for (const mw of middlewares) {
      if (mw.path) {
        const keys = [];
        const regexStr = mw.path.replace(/:([^/]+)/g, (_, k) => { keys.push(k); return '([^/]+)'; });
        const match = new RegExp('^' + regexStr + '$').exec(url);
        if (match && (mw.method === method || !mw.method)) {
          keys.forEach((k, idx) => req.params[k] = match[idx + 1]);
        }
      }
    }

    async function next(err) {
      const layer = middlewares[i++];
      if (!layer) return;

      const pathMatch = !layer.path
        ? true
        : (() => {
            const keys = [];
            const rs = layer.path.replace(/:([^/]+)/g, (_, k) => { keys.push(k); return '([^/]+)'; });
            return new RegExp('^' + rs + '$').test(url);
          })();

      const methodMatch = !layer.method || layer.method === method;

      if (err) {
        // error handler: fn.length === 4
        if (layer.fn.length === 4 && (!layer.path || pathMatch)) {
          return layer.fn(err, req, res, next);
        }
        return next(err); // skip normal middleware
      }

      if (!pathMatch || !methodMatch) return next();
      try {
        if (layer.fn.length === 4) return next(); // skip error mw in normal flow
        await layer.fn(req, res, next);
      } catch (e) {
        next(e);
      }
    }

    await next();
    return { req, res };
  }

  const app = {
    _middlewares: middlewares,
    use(pathOrFn, fn) {
      if (typeof pathOrFn === 'function') middlewares.push({ fn: pathOrFn });
      else                               middlewares.push({ path: pathOrFn, fn });
    },
    get   (path, fn) { middlewares.push({ method: 'GET',    path, fn }); },
    post  (path, fn) { middlewares.push({ method: 'POST',   path, fn }); },
    delete(path, fn) { middlewares.push({ method: 'DELETE', path, fn }); },
    listen(port, cb) { cb && cb(); return { close() {} }; },
    dispatch,
  };

  // express.json() – parse body string to object (body already parsed in mock)
  app.json = () => (req, res, next) => next();
  app.urlencoded = () => (req, res, next) => next();

  return Object.assign(() => app, app, {
    json:        () => (req, res, next) => next(),
    urlencoded:  () => (req, res, next) => next(),
  });
}

