'use strict';
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

// ── 1. AppError base ────────────────────────────────────────────────────────
const base = new AppError('base message', 503, 'BASE_CODE', { x: 1 });
console.assert(base.message    === 'base message',    'AppError: message');
console.assert(base.statusCode === 503,               'AppError: statusCode');
console.assert(base.errorCode  === 'BASE_CODE',       'AppError: errorCode');
console.assert(base.isOperational === true,           'AppError: isOperational');
console.assert(base.name       === 'AppError',        'AppError: name');
const json = base.toJSON();
console.assert(json.error.message === 'base message', 'AppError.toJSON: message');
console.assert(json.error.code    === 'BASE_CODE',    'AppError.toJSON: code');
console.assert(json.error.details.x === 1,            'AppError.toJSON: details');
console.log('[PASS] AppError base class');

// ── 2. NotFoundError ────────────────────────────────────────────────────────
const nfe = new NotFoundError('User not found', 'USER_NOT_FOUND', { userId: 99 });
console.assert(nfe.statusCode      === 404,             'NotFoundError: statusCode');
console.assert(nfe.errorCode       === 'USER_NOT_FOUND','NotFoundError: errorCode');
console.assert(nfe.name            === 'NotFoundError', 'NotFoundError: name');
console.assert(nfe.isOperational   === true,            'NotFoundError: isOperational');
console.assert(nfe instanceof AppError,                 'NotFoundError instanceof AppError');
console.assert(nfe instanceof Error,                    'NotFoundError instanceof Error');
// defaults
const nfeD = new NotFoundError();
console.assert(nfeD.message   === 'Resource not found', 'NotFoundError: default message');
console.assert(nfeD.errorCode === 'NOT_FOUND',          'NotFoundError: default errorCode');
console.log('[PASS] NotFoundError');

// ── 3. ValidationError ──────────────────────────────────────────────────────
const ve = new ValidationError('Email required', 'EMAIL_REQUIRED', { field: 'email' });
console.assert(ve.statusCode    === 400,               'ValidationError: statusCode');
console.assert(ve.errorCode     === 'EMAIL_REQUIRED',  'ValidationError: errorCode');
console.assert(ve.name          === 'ValidationError', 'ValidationError: name');
console.assert(ve.isOperational === true,              'ValidationError: isOperational');
console.assert(ve.details.field === 'email',           'ValidationError: details');
console.assert(ve instanceof AppError,                 'ValidationError instanceof AppError');
// defaults
const veD = new ValidationError();
console.assert(veD.message   === 'Validation failed',  'ValidationError: default message');
console.assert(veD.errorCode === 'VALIDATION_ERROR',   'ValidationError: default errorCode');
console.log('[PASS] ValidationError');

// ── 4. DatabaseError ────────────────────────────────────────────────────────
const cause = new Error('pg connection refused');
const dbe = new DatabaseError('DB query failed', 'DB_QUERY_FAILED', { table: 'users' }, cause);
