/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Every class extends the built-in Error so that:
 *  - instanceof checks work correctly throughout the codebase
 *  - stack traces are captured automatically
 *  - the centralised error-handling middleware can branch on class type
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

/**
 * AppError is the root class for every intentional, "known" error thrown in
 * this application.  Unknown / unexpected errors (e.g. programming mistakes,
 * third-party library crashes) remain plain Error instances so that the
 * middleware can distinguish them and respond with a generic 500.
 *
 * @property {number}  statusCode - HTTP status code sent to the client.
 * @property {string}  code       - Machine-readable error identifier.
 * @property {boolean} isOperational - true  → expected error, log at warn level.
 *                                     false → unexpected error, log at error level.
 */
class AppError extends Error {
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Preserve the real class name in stack traces (Node ≥ 6).
    this.name = this.constructor.name;

    this.statusCode    = statusCode;
    this.code          = code;
    this.isOperational = isOperational;

    // Capture V8 stack trace, excluding the constructor frame itself.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 – resource not found
// ---------------------------------------------------------------------------

/**
 * Thrown when a requested resource does not exist.
 *
 * @example
 *   throw new NotFoundError('User not found', { userId: id });
 *
 * @property {object} [details] - Optional context (e.g. the id that was looked up).
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message='Resource not found']
   * @param {object} [details={}] - Extra context included in the JSON response.
   */
  constructor(message = 'Resource not found', details = {}) {
    super(message, 404, 'NOT_FOUND');
    this.details = details;
  }
}

// ---------------------------------------------------------------------------
// 422 – validation / bad input
// ---------------------------------------------------------------------------

/**
 * Thrown when user-supplied input fails validation.
 *
 * @example
 *   throw new ValidationError('Invalid email address', { field: 'email' });
 *
 * @property {object} [details] - Field-level validation messages forwarded to
 *                                 the client so they can fix the request.
 */
class ValidationError extends AppError {
  /**
   * @param {string} [message='Validation failed']
   * @param {object} [details={}] - Field / constraint details.
   */
  constructor(message = 'Validation failed', details = {}) {
    super(message, 422, 'VALIDATION_ERROR');
    this.details = details;
  }
}

// ---------------------------------------------------------------------------
// 503 – database / persistence error
// ---------------------------------------------------------------------------

/**
 * Thrown when a database operation fails (connection error, query timeout,
 * constraint violation that cannot be surfaced as a ValidationError, etc.).
 *
 * DatabaseError is marked as *non*-operational (isOperational = false) because
 * its root cause is typically infrastructure rather than bad user input — the
 * middleware will log it at error level and hide internals from the client.
 *
 * @example
 *   throw new DatabaseError('Connection timed out', { query: 'SELECT …' });
 *
 * @property {object} [details] - Internal context for server-side logs only.
 *                                 Never forwarded to the client.
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message='A database error occurred']
   * @param {object} [details={}] - Internal diagnostics (NOT sent to client).
   */
  constructor(message = 'A database error occurred', details = {}) {
    // isOperational = false → treated as an unexpected error by the middleware.
    super(message, 503, 'DATABASE_ERROR', false);
    this.details = details;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

'use strict';

// ---------------------------------------------------------------------------
// Dependencies
// ---------------------------------------------------------------------------

const express = require('express');
const { AppError, NotFoundError, DatabaseError } = require('./errors');

const app = express();

app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Liveness probe — always returns 200 while the process is alive.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns the full list of users.
 *
 * Simulated failure path: pass ?fail=db in the query string to exercise the
 * DatabaseError branch without needing a real database.
 */
app.get('/users', (req, res) => {
  // --- Simulated database failure (for demonstration / testing) ------------
  if (req.query.fail === 'db') {
    throw new DatabaseError('Could not retrieve users', {
      query: 'SELECT * FROM users',
    });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

/**
 * GET /users/:id
 * Returns a single user by numeric id.
 *
 * Demonstrates both ValidationError (non-numeric id) and NotFoundError
 * (valid id but no matching record).
 */
app.get('/users/:id', (req, res) => {
  const { ValidationError } = require('./errors');

  const id = Number(req.params.id);

  // Guard: id must be a positive integer.
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('User ID must be a positive integer', {
      field: 'id',
      received: req.params.id,
    });
  }

  // Simulated data store.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  const user = users.find((u) => u.id === id);

  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`, { userId: id });
  }

  res.json(user);
});

// ---------------------------------------------------------------------------
// 404 catch-all (must come after all real routes)
// ---------------------------------------------------------------------------

/**
 * Any request that reaches this point matched no route — surface it as a
 * structured NotFoundError so the centralised handler formats it uniformly.
 */
app.use((req, res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
// ---------------------------------------------------------------------------

/**
 * Express identifies error-handling middleware by its four-argument signature
 * (err, req, res, next).  This must be the LAST middleware registered.
 *
 * Behaviour matrix:
 *
 * | Error type          | isOperational | Status | Body details shown? | Log level |
 * |---------------------|---------------|--------|---------------------|-----------|
 * | NotFoundError       | true          | 404    | yes                 | warn      |
 * | ValidationError     | true          | 422    | yes                 | warn      |
 * | DatabaseError       | false         | 503    | no (hidden)         | error     |
 * | Unknown / plain Err | false         | 500    | no (hidden)         | error     |
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ------------------------------------------------------------------
  // 1. Determine whether this is a known, intentional application error.
  // ------------------------------------------------------------------
  const isAppError = err instanceof AppError;

  // ------------------------------------------------------------------
  // 2. Normalise status code.
  //    • AppError subclasses carry their own statusCode.
  //    • Anything else defaults to 500.
  // ------------------------------------------------------------------
  const statusCode = isAppError ? err.statusCode : 500;

  // ------------------------------------------------------------------
  // 3. Log — structured so it can be ingested by log aggregators.
  //    Operational errors are expected; log at warn to avoid alert fatigue.
  //    Non-operational / unknown errors are bugs; log at error with full stack.
  // ------------------------------------------------------------------
  const logPayload = {
    code:    isAppError ? err.code : 'INTERNAL_ERROR',
    message: err.message,
    method:  req.method,
    path:    req.path,
    status:  statusCode,
    stack:   err.stack,
  };

  if (isAppError && err.isOperational) {
    console.warn('[WARN]', JSON.stringify(logPayload));
  } else {
    console.error('[ERROR]', JSON.stringify(logPayload));
  }

  // ------------------------------------------------------------------
  // 4. Build the client-facing response body.
  //
  //    For operational errors (NotFoundError, ValidationError) we can
  //    safely echo error details back to the caller — they originate from
  //    user input and contain nothing sensitive.
  //
  //    For non-operational errors (DatabaseError, unknown crashes) we
  //    return only a generic message so that internal diagnostics —
  //    connection strings, query text, stack traces — are never leaked.
  // ------------------------------------------------------------------
  const exposeDetails = isAppError && err.isOperational;

  const body = {
    error: {
      code:    isAppError ? err.code    : 'INTERNAL_ERROR',
      message: isAppError ? err.message : 'An unexpected error occurred',
      // Only attach details when it is safe to do so.
      ...(exposeDetails && err.details && Object.keys(err.details).length > 0
        ? { details: err.details }
        : {}),
    },
  };

  res.status(statusCode).json(body);
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

