const app = require('./app');
const http = require('http');

const server = app.listen(0, async () => {
  const { port } = server.address();
  const base = \`http://localhost:\${port}\`;

  async function hit(path) {
    return new Promise((resolve) => {
      http.get(\`\${base}\${path}\`, (res) => {
        let data = '';
        res.on('data', (c) => (data += c));
        res.on('end', () => resolve({ status: res.statusCode, body: JSON.parse(data) }));
      });
    });
  }

  const results = await Promise.all([
    hit('/health'),          // 200
    hit('/users'),           // 200
    hit('/users/1'),         // 200
    hit('/users/99'),        // 404 NotFoundError
    hit('/users/abc'),       // 422 ValidationError
    hit('/users?fail=db'),   // 503 DatabaseError
    hit('/no-such-route'),   // 404 catch-all
  ]);

  const labels = [
    'GET /health          ',
    'GET /users           ',
    'GET /users/1         ',
    'GET /users/99        ',
    'GET /users/abc       ',
    'GET /users?fail=db   ',
    'GET /no-such-route   ',
  ];

  results.forEach((r, i) => {
    const ok = [200,200,200,404,422,503,404][i] === r.status ? '✓' : '✗';
    console.log(\`\${ok} \${labels[i]} → \${r.status}  \${JSON.stringify(r.body)}\`);
  });

  server.close();
});
