# No network / npm available — run a self-contained unit test using only
# Node builtins: validate the error class hierarchy and shape directly.
node - << 'EOF'
'use strict';
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

let passed = 0;
let failed = 0;

function assert(condition, label) {
  if (condition) { console.log('  ✓', label); passed++; }
  else           { console.error('  ✗', label); failed++; }
}

// ── AppError base ──────────────────────────────────────────────────────────
console.log('\nAppError');
const base = new AppError('base msg', 418, 'TEAPOT');
assert(base instanceof Error,    'extends Error');
assert(base instanceof AppError, 'instanceof AppError');
assert(base.statusCode  === 418, 'statusCode 418');
assert(base.errorCode   === 'TEAPOT', 'errorCode TEAPOT');
assert(base.isOperational === true,   'isOperational defaults true');
assert(base.message     === 'base msg', 'message preserved');
assert(base.name        === 'AppError', 'name is class name');
assert(typeof base.stack === 'string',  'stack is present');

// ── NotFoundError ──────────────────────────────────────────────────────────
console.log('\nNotFoundError');
const nf = new NotFoundError();
assert(nf instanceof NotFoundError, 'instanceof NotFoundError');
assert(nf instanceof AppError,      'instanceof AppError');
assert(nf.statusCode  === 404,      'statusCode 404');
assert(nf.errorCode   === 'NOT_FOUND', 'default errorCode');
assert(nf.message     === 'Resource not found', 'default message');
assert(nf.isOperational === true,   'isOperational true');

const nfCustom = new NotFoundError('User not found', 'USER_NOT_FOUND');
assert(nfCustom.message   === 'User not found',   'custom message');
assert(nfCustom.errorCode === 'USER_NOT_FOUND',   'custom errorCode');

// ── ValidationError ────────────────────────────────────────────────────────
console.log('\nValidationError');
const ve = new ValidationError();
assert(ve instanceof ValidationError, 'instanceof ValidationError');
assert(ve instanceof AppError,        'instanceof AppError');
assert(ve.statusCode  === 422,        'statusCode 422');
assert(ve.errorCode   === 'VALIDATION_ERROR', 'default errorCode');
assert(ve.message     === 'Validation failed', 'default message');
