/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Every class extends the base AppError, which carries:
 *  - statusCode  – the HTTP status that will be sent to the client
 *  - isOperational – true for "expected" errors (4xx, known 5xx) so the
 *                    global handler knows it is safe to expose the message
 */

'use strict';

// ---------------------------------------------------------------------------
// Base class
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message       Human-readable description of the error.
   * @param {number}  statusCode    HTTP status code to return to the caller.
   * @param {string}  [errorCode]   Optional machine-readable code, e.g.
   *                                "USER_NOT_FOUND", for API consumers to
   *                                branch on without parsing the message.
   */
  constructor(message, statusCode, errorCode) {
    super(message);

    // Keep the prototype chain intact so `instanceof` checks work correctly
    // when the class is transpiled by Babel / older Node versions.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.errorCode   = errorCode || this.constructor.name.toUpperCase();
    this.isOperational = true;          // distinguish from unexpected crashes
    this.timestamp   = new Date().toISOString();

    // Capture a clean stack trace that starts at the call-site, not inside
    // this constructor.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /**
   * Serialise the error into the standard JSON response shape.
   * The global error handler calls this method so the format is always
   * consistent, regardless of which subclass was thrown.
   *
   * @param  {boolean} includeStack – only true in development
   * @returns {{ error: object }}
   */
  toJSON(includeStack = false) {
    const body = {
      error: {
        name:      this.name,
        code:      this.errorCode,
        message:   this.message,
        status:    this.statusCode,
        timestamp: this.timestamp,
      },
    };

    if (includeStack) {
      body.error.stack = this.stack;
    }

    return body;
  }
}

// ---------------------------------------------------------------------------
// 400 Bad Request – input / validation failures
// ---------------------------------------------------------------------------

/**
 * Thrown when incoming data fails validation rules.
 *
 * @example
 *   throw new ValidationError('email must be a valid address');
 *
 * @example  – with structured field-level details
 *   throw new ValidationError('Request body is invalid', [
 *     { field: 'email', message: 'must be a valid address' },
 *     { field: 'age',   message: 'must be a positive integer' },
 *   ]);
 */
class ValidationError extends AppError {
  /**
   * @param {string}   message
   * @param {Array<{ field: string, message: string }>} [details]
   *   Optional per-field breakdown returned to API consumers.
   */
  constructor(message = 'Validation failed', details = []) {
    super(message, 400, 'VALIDATION_ERROR');
    this.details = details;   // [] is safe – no field info leaked when unused
  }

  toJSON(includeStack = false) {
    const json = super.toJSON(includeStack);
    if (this.details.length > 0) {
      json.error.details = this.details;
    }
    return json;
  }
}

// ---------------------------------------------------------------------------
// 404 Not Found
// ---------------------------------------------------------------------------

/**
 * Thrown when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User', userId);
 *   // → "User with id 42 was not found"
 *
 * @example  – bare, for unknown routes
 *   throw new NotFoundError();
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [resource]  Name of the resource type, e.g. "User".
   * @param {string|number} [id] Identifier that was looked up.
   */
  constructor(resource, id) {
    const message =
      resource && id !== undefined
        ? `${resource} with id ${id} was not found`
        : resource
        ? `${resource} was not found`
        : 'The requested resource was not found';

    super(message, 404, 'NOT_FOUND');
    this.resource = resource || null;
    this.resourceId = id !== undefined ? id : null;
  }
}

// ---------------------------------------------------------------------------
// 500 Internal Server Error – database / persistence failures
// ---------------------------------------------------------------------------

/**
 * Thrown when an interaction with the database fails in an unexpected way.
 * The original low-level error is captured but its details are **never**
 * forwarded to API consumers in production; they are available on the
 * instance for server-side logging only.
 *
 * @example
 *   try {
 *     await db.query(sql, params);
 *   } catch (cause) {
 *     throw new DatabaseError('Failed to fetch users', cause);
 *   }
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message]  High-level description safe to log.
   * @param {Error}  [cause]    Original error from the database driver.
   */
  constructor(
    message = 'A database error occurred',
    cause   = null,
  ) {
    super(message, 500, 'DATABASE_ERROR');

    // `cause` is the Node 16.9+ built-in Error option; mirror it manually
    // so it works on older runtimes too.
    this.cause = cause;

    // Operational = false means the global handler will log aggressively and
    // may choose to send a generic "Internal Server Error" body in production.
    this.isOperational = false;
  }

  toJSON(includeStack = false) {
    const json = super.toJSON(includeStack);
    // Expose the underlying DB message only when the full stack is included
    // (i.e. development mode), so it never leaks in production.
    if (includeStack && this.cause) {
      json.error.cause = this.cause.message;
    }
    return json;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  ValidationError,
  NotFoundError,
  DatabaseError,
};

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

// ---------------------------------------------------------------------------
// Body parsing
// ---------------------------------------------------------------------------
app.use(express.json());

// ---------------------------------------------------------------------------
// In-memory data store (stand-in for a real database layer)
// ---------------------------------------------------------------------------
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Basic liveness probe – always succeeds.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns the full list of users.
 *
 * Simulates a DatabaseError when the query-string flag ?fail=1 is supplied
 * so the error path can be exercised without a real database.
 */
app.get('/users', (req, res, next) => {
  try {
    // Simulate an unexpected database failure for demonstration / testing.
    if (req.query.fail === '1') {
      throw new DatabaseError(
        'Failed to retrieve users',
        new Error('connection timeout'),  // the raw driver error
      );
    }

    res.json(users);
  } catch (err) {
    next(err);
  }
});

/**
 * GET /users/:id
 * Returns a single user by id.
 *
 * Throws:
 *  - ValidationError (400) – id is not a positive integer
 *  - NotFoundError   (404) – no user with that id exists
 */
app.get('/users/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (!Number.isInteger(id) || id < 1) {
      throw new ValidationError('User id must be a positive integer', [
        { field: 'id', message: 'must be a positive integer' },
      ]);
    }

    const user = users.find((u) => u.id === id);
    if (!user) {
      throw new NotFoundError('User', id);
    }

    res.json(user);
  } catch (err) {
    next(err);
  }
});

/**
 * POST /users
 * Creates a new user.
 *
 * Throws:
 *  - ValidationError (400) – name or email is missing / malformed
 */
app.post('/users', (req, res, next) => {
  try {
    const { name, email } = req.body ?? {};
    const validationDetails = [];

    if (!name || typeof name !== 'string' || name.trim() === '') {
      validationDetails.push({ field: 'name', message: 'name is required and must be a non-empty string' });
    }

    if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      validationDetails.push({ field: 'email', message: 'email is required and must be a valid address' });
    }

    if (validationDetails.length > 0) {
      throw new ValidationError('Request body failed validation', validationDetails);
    }

    const newUser = { id: users.length + 1, name: name.trim(), email };
    users.push(newUser);

    res.status(201).json(newUser);
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// 404 catch-all  (must come AFTER all real routes)
// ---------------------------------------------------------------------------
app.use((req, res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.path} does not exist`));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
// (4-argument signature tells Express this is an error handler)
// ---------------------------------------------------------------------------

/**
 * Formats and sends every error that has been passed to next(err) from any
 * route or middleware.
 *
 * Behaviour:
 *  - Operational AppErrors  → use their own statusCode + toJSON()
 *  - Non-operational errors → 500, with a generic message in production so
 *                             internal details are never leaked to callers
 *  - Stack traces           → only included when NODE_ENV === 'development'
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV === 'development';

  // Always log the full error server-side for observability.
  console.error({
    message:   err.message,
    code:      err.errorCode  ?? 'UNKNOWN',
    status:    err.statusCode ?? 500,
    path:      `${req.method} ${req.originalUrl}`,
    stack:     err.stack,
    ...(err.cause ? { cause: err.cause.message } : {}),
  });

  // --- Known / operational application errors --------------------------------
  if (err instanceof AppError) {
    return res
      .status(err.statusCode)
      .json(err.toJSON(isDev));
  }

  // --- Handle express's built-in JSON parse error ----------------------------
  // express.json() throws a SyntaxError with status 400 when the body is
  // malformed; wrap it into our own shape so the response is consistent.
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    const wrapped = new ValidationError('Request body contains invalid JSON');
    return res
      .status(wrapped.statusCode)
      .json(wrapped.toJSON(isDev));
  }

  // --- Unexpected / non-operational errors -----------------------------------
  // In production we hide implementation details; in development we expose
  // the real message and stack to ease debugging.
  const statusCode = err.statusCode ?? 500;
  const message    = isDev ? err.message : 'An unexpected error occurred. Please try again later.';

  return res.status(statusCode).json({
    error: {
      name:      'InternalServerError',
      code:      'INTERNAL_SERVER_ERROR',
      message,
      status:    statusCode,
      timestamp: new Date().toISOString(),
      ...(isDev ? { stack: err.stack } : {}),
    },
  });
});

// ---------------------------------------------------------------------------
// Start server (only when this file is run directly, not when it is imported
// by tests or other modules)
// ---------------------------------------------------------------------------
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

