// ── AppError base ────────────────────────────────────────────────────────────
const base = new AppError('something went wrong', 418, 'TEAPOT');
console.assert(base.statusCode    === 418,             'base: statusCode');
console.assert(base.errorCode     === 'TEAPOT',        'base: errorCode');
console.assert(base.isOperational === true,            'base: isOperational');
console.assert(base instanceof Error,                  'base: instanceof Error');
console.assert(base instanceof AppError,               'base: instanceof AppError');
