// ─── Minimal Express mock ────────────────────────────────────────────────────
// Only the subset of the Express API that app.js and the tests actually use.

function createMockApp() {
  const routes  = [];     // { method, path, handler }
  const mw      = [];     // regular middleware stack
  const errMw   = [];     // error-handler stack (4-arg)

  // match /foo/:bar style paths, return params or null
  function matchRoute(pattern, urlPath) {
    const keys   = [];
    const re     = pattern.replace(/:([^/]+)/g, (_, k) => { keys.push(k); return '([^/]+)'; });
    const m      = urlPath.match(new RegExp('^' + re + '$'));
    if (!m) return null;
    return Object.fromEntries(keys.map((k, i) => [k, m[i + 1]]));
  }

  function use(...args) {
    const handler = args[args.length - 1];
    if (typeof handler === 'function') {
      if (handler.length === 4) { errMw.push(handler); }
      else                      { mw.push({ path: typeof args[0] === 'string' ? args[0] : null, handler }); }
    }
  }
  function addRoute(method, path, handler) {
    routes.push({ method: method.toUpperCase(), path, handler });
  }

  const app = {
    use,
    get:  (p, h) => addRoute('GET',  p, h),
    post: (p, h) => addRoute('POST', p, h),
    // simulate a request, returns { status, body }
    async simulate(method, urlWithQuery, reqBody) {
      const [urlPath, qs = ''] = urlWithQuery.split('?');
      const query = Object.fromEntries(new URLSearchParams(qs));

      let statusCode = 200;
      let responseBody;

      const res = {
        status(code) { statusCode = code; return res; },
        json(data)   { responseBody = data; },
      };

      let nextCalled = false;
      let nextErr;

      const next = (err) => {
        nextCalled = true;
        nextErr = err;
      };

      // 1. Run regular middleware (only express.json equivalent – skip here)
      // 2. Match route
      let matched = false;
      for (const route of routes) {
        if (route.method !== method.toUpperCase()) continue;
        const params = matchRoute(route.path, urlPath);
        if (params === null) continue;

        matched = true;
        nextCalled = false; nextErr = undefined;
        const req = { params, query, body: reqBody ?? {}, method, path: urlPath, originalUrl: urlWithQuery };
        route.handler(req, res, next);

        if (nextCalled && nextErr) break;
        if (!nextCalled) return { status: statusCode, body: responseBody };
      }

      // 3. Catch-all 404 middleware (use() with no path)
      if (!matched || (nextCalled && nextErr === undefined)) {
        const req = { method, path: urlPath, originalUrl: urlWithQuery, params: {}, query, body: {} };
        for (const m2 of mw) {
          nextCalled = false; nextErr = undefined;
          m2.handler(req, res, next);
          if (nextCalled && nextErr) break;
        }
      }

      // 4. Error handlers
      if (nextErr) {
        const req = { method, path: urlPath, originalUrl: urlWithQuery };
        for (const eh of errMw) {
          nextCalled = false;
          eh(nextErr, req, res, next);
          if (!nextCalled) return { status: statusCode, body: responseBody };
        }
      }

      return { status: statusCode, body: responseBody };
    },
  };

  return app;
}

// ─── Patch require so errors.js loads normally but app.js uses mock ──────────
const Module   = require('module');
const origLoad = Module._load;
let mockApp;

Module._load = function(id, parent, isMain) {
  if (id === 'express') {
    return function() {
      mockApp = createMockApp();
      // expose the real express.json no-op
      mockApp.use = ((orig) => function(...args) {
        // skip the express.json() call silently
        if (args.length === 1 && typeof args[0] === 'function' && args[0].toString().includes('express.json')) return;
        orig.apply(mockApp, args);
      })(mockApp.use);
      return mockApp;
    };
  }
  return origLoad.apply(this, arguments);
};

