/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Every class extends the base AppError, which carries:
 *   - message   – human-readable description
 *   - statusCode – HTTP status code sent to the client
 *   - code       – machine-readable error identifier (useful for clients / logs)
 *   - isOperational – distinguishes expected errors (true) from programmer
 *                     bugs (false) so the global handler can decide whether
 *                     to restart the process in production.
 */

'use strict';

// ─── Base class ──────────────────────────────────────────────────────────────

class AppError extends Error {
  /**
   * @param {string} message       - Human-readable error description.
   * @param {number} statusCode    - HTTP status code (e.g. 400, 404, 500).
   * @param {string} code          - Machine-readable error code (e.g. 'NOT_FOUND').
   * @param {boolean} isOperational - true = expected/handled error;
   *                                  false = programmer error / unexpected fault.
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Restore the correct prototype chain so `instanceof` checks work after
    // TypeScript / Babel transpilation and in plain Node.js alike.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name       = this.constructor.name;
    this.statusCode = statusCode;
    this.code       = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call-site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ─── 404 Not Found ───────────────────────────────────────────────────────────

/**
 * Thrown when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User not found', 'USER_NOT_FOUND');
 *   throw new NotFoundError(`Product ${id} not found`);   // code defaults to 'NOT_FOUND'
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message='Resource not found']
   * @param {string} [code='NOT_FOUND']
   */
  constructor(message = 'Resource not found', code = 'NOT_FOUND') {
    super(message, 404, code);
  }
}

// ─── 400 Validation Error ────────────────────────────────────────────────────

/**
 * Thrown when incoming request data fails validation rules.
 * Optionally carries a `fields` map so callers receive per-field feedback.
 *
 * @example
 *   throw new ValidationError('Invalid email address');
 *   throw new ValidationError('Validation failed', { email: 'must be a valid email' });
 */
class ValidationError extends AppError {
  /**
   * @param {string} [message='Validation failed']
   * @param {Object} [fields={}]  - Optional map of { fieldName: errorMessage }.
   * @param {string} [code='VALIDATION_ERROR']
   */
  constructor(message = 'Validation failed', fields = {}, code = 'VALIDATION_ERROR') {
    super(message, 400, code);
    // Attach field-level detail so the handler can forward it to the client.
    this.fields = fields;
  }
}

// ─── 503 Database Error ──────────────────────────────────────────────────────

/**
 * Thrown when a database operation fails (connection issue, query error, etc.).
 * The original database error is stored as `cause` for internal logging but is
 * never forwarded to the client to avoid leaking implementation details.
 *
 * @example
 *   throw new DatabaseError('Failed to fetch users', originalPgError);
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message='A database error occurred']
   * @param {Error|null} [cause=null]  - The underlying driver/ORM error.
   * @param {string} [code='DATABASE_ERROR']
   */
  constructor(
    message = 'A database error occurred',
    cause   = null,
    code    = 'DATABASE_ERROR',
  ) {
    // 503 Service Unavailable — the server cannot fulfil the request right now.
    super(message, 503, code);
    // Store the root cause for server-side logging without surfacing it in
    // the HTTP response.
    this.cause = cause;
  }
}

// ─── Exports ─────────────────────────────────────────────────────────────────

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

'use strict';

/**
 * errorHandler.js
 * Express centralised error-handling middleware.
 *
 * Must be registered AFTER all routes with exactly four parameters so that
 * Express recognises it as an error handler:
 *
 *   app.use(errorHandler);
 *
 * Behaviour
 * ─────────
 *  • Operational errors (AppError subclasses)  → structured JSON response
 *    using the error's own statusCode and code.
 *  • Unrecognised / programmer errors           → 500 Internal Server Error
 *    with no internal detail leaked to the client.
 *  • The original error is always logged to stderr so nothing is silently
 *    swallowed; swap `console.error` for your logger (Winston, Pino, etc.)
 *    without changing any other code.
 */

const { AppError, ValidationError } = require('./errors');

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Build the JSON body that is sent back to the client.
 * Internal detail (stack traces, raw DB errors) is only included when
 * NODE_ENV is not 'production'.
 *
 * @param {Error}   err
 * @param {boolean} includeDetail
 * @returns {Object}
 */
function buildResponseBody(err, includeDetail) {
  const isAppError = err instanceof AppError;

  const body = {
    error: {
      code:    isAppError ? err.code    : 'INTERNAL_SERVER_ERROR',
      message: isAppError ? err.message : 'An unexpected error occurred',
    },
  };

  // Attach per-field validation detail when present.
  if (err instanceof ValidationError && Object.keys(err.fields).length > 0) {
    body.error.fields = err.fields;
  }

  // Attach stack trace / cause only in non-production for easier debugging.
  if (includeDetail) {
    body.error.stack = err.stack;

    // Surface the underlying cause for DatabaseError etc., but only
    // server-side (i.e. only when we are in dev/test mode).
    if (err.cause) {
      body.error.cause = err.cause.message ?? String(err.cause);
    }
  }

  return body;
}

// ─── Middleware ───────────────────────────────────────────────────────────────

/**
 * Centralised Express error-handling middleware.
 *
 * @param {Error}             err
 * @param {import('express').Request}  req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next   - Required by Express even if unused.
 */
// eslint-disable-next-line no-unused-vars
function errorHandler(err, req, res, next) {
  const isDev          = process.env.NODE_ENV !== 'production';
  const isAppError     = err instanceof AppError;
  const statusCode     = isAppError ? err.statusCode : 500;

  // ── Logging ────────────────────────────────────────────────────────────────
  // Always log the full error server-side.
  // Operational errors get a concise warning; unexpected errors get the full
  // stack so they are easy to trace.
  if (isAppError && err.isOperational) {
    console.warn(
      `[${new Date().toISOString()}] ${err.name} (${err.code}) [${statusCode}] — ${err.message}`,
    );
  } else {
    console.error(
      `[${new Date().toISOString()}] Unhandled error on ${req.method} ${req.originalUrl}:`,
      err,
    );
  }

  // ── Response ───────────────────────────────────────────────────────────────
  // Guard against trying to send headers after they have already been sent
  // (e.g. error thrown mid-stream).
  if (res.headersSent) {
    return next(err);
  }

  return res
    .status(statusCode)
    .json(buildResponseBody(err, isDev));
}

module.exports = errorHandler;

'use strict';

/**
 * app.js
 * Express application entry-point.
 *
 * Error handling strategy
 * ───────────────────────
 * Routes no longer call res.status().json() inline for error cases.
 * Instead they throw (sync routes) or call next(err) (async routes) with a
 * typed error from errors.js.  A single errorHandler middleware registered at
 * the bottom converts every error into a consistent JSON response.
 */

const express = require('express');

const errorHandler              = require('./errorHandler');
const { NotFoundError,
        ValidationError,
        DatabaseError }         = require('./errors');

const app = express();

// ─── Global middleware ────────────────────────────────────────────────────────

app.use(express.json());

// ─── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Liveness probe — always returns 200 while the process is alive.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns the full list of users.
 *
 * Error cases:
 *   • Any database failure  → DatabaseError (503)
 */
app.get('/users', async (req, res, next) => {
  try {
    // Simulated data layer — replace with a real DB call.
    const users = await getUsers();
    res.json(users);
  } catch (err) {
    // Re-wrap unexpected DB/driver errors so the handler knows the origin.
    next(err instanceof DatabaseError ? err : new DatabaseError('Failed to fetch users', err));
  }
});

/**
 * GET /users/:id
 * Returns a single user by numeric ID.
 *
 * Error cases:
 *   • Non-numeric id param  → ValidationError (400)
 *   • User not found        → NotFoundError   (404)
 *   • Database failure      → DatabaseError   (503)
 */
app.get('/users/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (!Number.isInteger(id) || id <= 0) {
      throw new ValidationError(
        'Invalid user id — must be a positive integer',
        { id: 'Must be a positive integer' },
      );
    }

    const user = await getUserById(id);

    if (!user) {
      throw new NotFoundError(`User ${id} not found`, 'USER_NOT_FOUND');
    }

    res.json(user);
  } catch (err) {
    next(err instanceof DatabaseError ? err : err.isOperational
      ? err                                              // already a typed AppError
      : new DatabaseError('Failed to fetch user', err), // unexpected error → wrap
    );
  }
});

/**
 * POST /users
 * Creates a new user.
 *
 * Expected body: { name: string, email: string }
 *
 * Error cases:
 *   • Missing / invalid body fields → ValidationError (400)
 *   • Database failure              → DatabaseError   (503)
 */
app.post('/users', async (req, res, next) => {
  try {
    const { name, email } = req.body ?? {};
    const fieldErrors     = {};

    if (!name || typeof name !== 'string' || name.trim() === '') {
      fieldErrors.name = 'name is required and must be a non-empty string';
    }

    if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      fieldErrors.email = 'email is required and must be a valid email address';
    }

    if (Object.keys(fieldErrors).length > 0) {
      throw new ValidationError('Request body validation failed', fieldErrors);
    }

    const newUser = await createUser({ name: name.trim(), email: email.trim() });
    res.status(201).json(newUser);
  } catch (err) {
    next(err.isOperational
      ? err
      : new DatabaseError('Failed to create user', err),
    );
  }
});

// ─── 404 catch-all ────────────────────────────────────────────────────────────
// Must come after all valid routes so only genuinely unknown paths reach it.

app.use((req, res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`, 'ROUTE_NOT_FOUND'));
});

// ─── Centralised error handler ────────────────────────────────────────────────
// Must be registered last and must declare exactly four parameters.

app.use(errorHandler);

// ─── Data-layer stubs ─────────────────────────────────────────────────────────
// Replace these with real database calls (e.g. via an ORM or query builder).
// They live here temporarily so the file is self-contained and runnable.

const _users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

async function getUsers() {
  return _users;
}

async function getUserById(id) {
  return _users.find((u) => u.id === id) ?? null;
}

async function createUser({ name, email }) {
  const newUser = { id: _users.length + 1, name, email };
  _users.push(newUser);
  return newUser;
}

// ─── Server bootstrap ─────────────────────────────────────────────────────────

const PORT = process.env.PORT ?? 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

