/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Every class extends the built-in Error so that:
 *  - instanceof checks work correctly throughout the codebase
 *  - Stack traces are captured automatically
 *  - The centralised error-handling middleware can branch on error type
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// All custom errors extend this class so the middleware can distinguish
// intentional, "known" errors from unexpected runtime errors.
// ---------------------------------------------------------------------------
class AppError extends Error {
  /**
   * @param {string}  message        - Human-readable description.
   * @param {number}  statusCode     - HTTP status code to send to the client.
   * @param {string}  errorCode      - Machine-readable code (for API consumers).
   * @param {object}  [details=null] - Optional structured detail payload.
   */
  constructor(message, statusCode, errorCode, details = null) {
    super(message);

    // Maintain the correct prototype chain so `instanceof AppError` works
    // even after TypeScript / Babel down-compilation.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name       = this.constructor.name;
    this.statusCode = statusCode;
    this.errorCode  = errorCode;
    this.details    = details;

    // Capture a clean V8 stack trace that starts at the call site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /**
   * Serialise the error to a plain object suitable for a JSON response body.
   * Sensitive internals (stack trace) are intentionally excluded.
   */
  toJSON() {
    const payload = {
      error: {
        name:      this.name,
        code:      this.errorCode,
        message:   this.message,
        statusCode: this.statusCode,
      },
    };

    if (this.details !== null && this.details !== undefined) {
      payload.error.details = this.details;
    }

    return payload;
  }
}

// ---------------------------------------------------------------------------
// 404 – NotFoundError
// Thrown when a requested resource cannot be located.
//
// Usage:
//   throw new NotFoundError('User not found', { id: 42 });
// ---------------------------------------------------------------------------
class NotFoundError extends AppError {
  /**
   * @param {string}  [message='Resource not found']
   * @param {object}  [details=null] - e.g. the identifier that was looked up.
   */
  constructor(message = 'Resource not found', details = null) {
    super(message, 404, 'NOT_FOUND', details);
  }
}

// ---------------------------------------------------------------------------
// 422 – ValidationError
// Thrown when incoming data fails validation rules.
//
// Usage:
//   throw new ValidationError('Invalid request body', [
//     { field: 'email', message: 'Must be a valid email address' },
//   ]);
// ---------------------------------------------------------------------------
class ValidationError extends AppError {
  /**
   * @param {string}        [message='Validation failed']
   * @param {Array|object}  [details=null] - Per-field error list or summary.
   */
  constructor(message = 'Validation failed', details = null) {
    super(message, 422, 'VALIDATION_ERROR', details);
  }
}

// ---------------------------------------------------------------------------
// 503 – DatabaseError
// Thrown when a database operation fails (connection issues, query errors …).
// 503 signals that the service is temporarily unavailable so callers know to
// retry, while hiding internal DB details from the public response.
//
// Usage:
//   throw new DatabaseError('Could not fetch users', { operation: 'SELECT' });
// ---------------------------------------------------------------------------
class DatabaseError extends AppError {
  /**
   * @param {string}  [message='A database error occurred']
   * @param {object}  [details=null]
   */
  constructor(message = 'A database error occurred', details = null) {
    super(message, 503, 'DATABASE_ERROR', details);
  }
}

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

/**
 * app.js
 * Express application with centralised error-handling middleware.
 *
 * Design principles applied:
 *  - Routes throw custom AppError subclasses; they never call res.status().json()
 *    directly for error paths.
 *  - A single error-handling middleware at the bottom of the stack catches
 *    every thrown / next(err) error and converts it to a consistent JSON shape.
 *  - A catch-all 404 route is registered after all valid routes so unmatched
 *    paths are handled uniformly through the same error pipeline.
 */

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

// ---------------------------------------------------------------------------
// Body parsing middleware
// ---------------------------------------------------------------------------
app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness probe – always succeeds.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns the list of all users.
 *
 * Throws DatabaseError when the data layer is unavailable.
 */
app.get('/users', (req, res) => {
  // Simulate a real data-access layer.
  // Replace this block with your actual DB call; throw DatabaseError on failure.
  const users = fetchUsersFromDB();
  res.json(users);
});

/**
 * GET /users/:id
 * Returns a single user by numeric id.
 *
 * Throws:
 *   ValidationError – when `:id` is not a positive integer.
 *   NotFoundError   – when no user with that id exists.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('User id must be a positive integer', {
      field: 'id',
      received: req.params.id,
    });
  }

  const user = findUserById(id);

  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`, { id });
  }

  res.json(user);
});

/**
 * POST /users
 * Creates a new user.
 *
 * Throws:
 *   ValidationError – when required fields are missing or malformed.
 *   DatabaseError   – when the insert operation fails.
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};

  // --- Input validation ---------------------------------------------------
  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'name is required and must be a non-empty string' });
  }

  if (!email || typeof email !== 'string' || !isValidEmail(email)) {
    fieldErrors.push({ field: 'email', message: 'email is required and must be a valid email address' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Invalid request body', fieldErrors);
  }

  // --- Persist the new user -----------------------------------------------
  const created = insertUserIntoDB({ name: name.trim(), email: email.trim() });
  res.status(201).json(created);
});

// ---------------------------------------------------------------------------
// 404 catch-all – must be registered AFTER all valid routes
// Transforms unmatched paths into a NotFoundError that flows through the
// centralised error handler below, keeping the response format consistent.
// ---------------------------------------------------------------------------
app.use((req, _res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.path} not found`));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
//
// Express identifies error-handling middleware by its four-argument signature
// (err, req, res, next).  It must be the LAST middleware registered.
//
// Responsibilities:
//   1. Distinguish known AppError subclasses from unexpected runtime errors.
//   2. Log unexpected errors with full stack traces (server-side only).
//   3. Send a structured JSON response without leaking internal details.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // --- Known, intentional errors (thrown by route handlers) ---------------
  if (err instanceof AppError) {
    return res.status(err.statusCode).json(err.toJSON());
  }

  // --- Unexpected / unhandled errors --------------------------------------
  // Log the full error server-side for observability, but never expose
  // stack traces or raw error messages to API consumers.
  console.error('[Unhandled Error]', {
    method:  req.method,
    path:    req.path,
    message: err.message,
    stack:   err.stack,
  });

  return res.status(500).json({
    error: {
      name:       'InternalServerError',
      code:       'INTERNAL_SERVER_ERROR',
      message:    'An unexpected error occurred. Please try again later.',
      statusCode: 500,
    },
  });
});

// ---------------------------------------------------------------------------
// Data-access helpers (stubs – replace with real DB logic)
// ---------------------------------------------------------------------------

/** In-memory user store used as a stand-in for a real database. */
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

/**
 * Fetch all users.
 * @returns {Array} List of user objects.
 * @throws  {DatabaseError} When the data layer is unavailable.
 */
function fetchUsersFromDB() {
  // Replace with a real DB query; wrap driver errors in DatabaseError, e.g.:
  //   try { return await db.query('SELECT * FROM users'); }
  //   catch (dbErr) { throw new DatabaseError('Failed to fetch users', { cause: dbErr.message }); }
  return users;
}

/**
 * Find a user by id.
 * @param   {number}      id
 * @returns {object|undefined} The user object, or undefined if not found.
 * @throws  {DatabaseError} When the data layer is unavailable.
 */
function findUserById(id) {
  return users.find((u) => u.id === id);
}

/**
 * Insert a new user.
 * @param   {{ name: string, email: string }} data
 * @returns {object} The newly created user (with generated id).
 * @throws  {DatabaseError} When the insert operation fails.
 */
function insertUserIntoDB(data) {
  const newUser = {
    id:    users.length + 1,
    name:  data.name,
    email: data.email,
  };
  users.push(newUser);
  return newUser;
}

/**
 * Minimal email format validator.
 * @param   {string} value
 * @returns {boolean}
 */
function isValidEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

// ---------------------------------------------------------------------------
// Server bootstrap (only when run directly, not when required by tests)
// ---------------------------------------------------------------------------
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

