'use strict';
// ── Minimal Express mock ──────────────────────────────────────────────────
const EventEmitter = require('events');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

// Build a tiny mock that records registered routes/middleware and lets us
// fire them manually, so we can test app.js end-to-end without the real
// Express package.
function makeMockExpress() {
  const stack = [];          // [{method, path, fn}]
  const errorStack = [];     // [{fn}]  (4-arg middleware)

  function app() {}          // callable but unused directly

  ['get', 'post', 'put', 'patch', 'delete'].forEach(method => {
    app[method] = (path, fn) => stack.push({ method, path, fn });
  });

  app.use = (...args) => {
    if (args.length === 1) {
      // Could be body-parser or error handler
      if (args[0].length === 4) errorStack.push({ fn: args[0] });
      else stack.push({ method: '*', path: '*', fn: args[0] });
    } else {
      // (path, fn) or (fn)
      const [path, fn] = args.length === 2 ? args : ['*', args[0]];
      if (fn && fn.length === 4) errorStack.push({ fn });
      else stack.push({ method: '*', path, fn: fn || path });
    }
  };

  app.listen = (port, cb) => { if (cb) cb(); return { close() {} }; };

  // Simulate a request and collect the response
  app.simulate = async (method, path, body = {}) => {
    const req = { method: method.toUpperCase(), path, params: {}, body,
                  query: {}, headers: {} };

    // Extract :param segments
    const res = {
      _status: 200, _body: null,
      status(code) { this._status = code; return this; },
      json(data)   { this._body  = data; return this; },
    };

    let errorThrown = null;
    const matchedHandlers = [];

    // Find matching route handlers
    for (const { method: m, path: p, fn } of stack) {
      const methodOk = m === '*' || m === method.toLowerCase();
      let params = {};
      let pathOk = false;

      if (p === '*' || p === path) {
        pathOk = true;
      } else {
        // Simple :param matching
        const routeRe = p.replace(/:([^/]+)/g, '([^/]+)');
        const paramNames = [...p.matchAll(/:([^/]+)/g)].map(m => m[1]);
        const match = path.match(new RegExp('^' + routeRe + '$'));
        if (match) {
          pathOk = true;
          paramNames.forEach((name, i) => { params[name] = match[i + 1]; });
        }
      }

      if (methodOk && pathOk) {
        matchedHandlers.push({ fn, params });
      }
    }

    // Execute handlers in order, stopping on throw
    for (const { fn, params } of matchedHandlers) {
      req.params = { ...req.params, ...params };
      try {
        // Skip the body-parser stub (it's express.json())
        if (fn._isMockBodyParser) continue;
        const result = fn(req, res, (err) => {
          if (err) errorThrown = err;
        });
        if (result && typeof result.catch === 'function') await result;
      } catch (e) {
        errorThrown = e;
        break;
      }
      if (errorThrown || res._body !== null) break;
    }

    // Run error handlers if needed
    if (errorThrown) {
      for (const { fn } of errorStack) {
        fn(errorThrown, req, res, () => {});
        if (res._body !== null) break;
      }
    }

    return { status: res._status, body: res._body };
  };

  return app;
}

// Patch require so 'express' returns our mock
const Module = require('module');
const _orig = Module._resolveFilename;
Module._resolveFilename = function(request, ...rest) {
  if (request === 'express') return 'express';
  return _orig.call(this, request, ...rest);
};
const _origLoad = Module._load;
const mockExpress = makeMockExpress();
mockExpress.json = () => { const fn = (_r,_s,n) => n(); fn._isMockBodyParser=true; return fn; };
Module._load = function(request, ...rest) {
  if (request === 'express') return mockExpress;
  return _origLoad.call(this, request, ...rest);
};

