/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Every class extends the built-in Error so that:
 *  - instanceof checks work correctly throughout the codebase
 *  - Stack traces are captured automatically
 *  - The centralised error-handling middleware can branch on error type
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// All custom errors extend this class so the middleware can distinguish
// intentional, "known" errors from unexpected runtime errors.
// ---------------------------------------------------------------------------
class AppError extends Error {
  /**
   * @param {string}  message        - Human-readable description.
   * @param {number}  statusCode     - HTTP status code to send to the client.
   * @param {string}  errorCode      - Machine-readable code (for API consumers).
   * @param {object}  [details=null] - Optional structured detail payload.
   */
  constructor(message, statusCode, errorCode, details = null) {
    super(message);

    // Maintain the correct prototype chain so `instanceof AppError` works
    // even after TypeScript / Babel down-compilation.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name       = this.constructor.name;
    this.statusCode = statusCode;
    this.errorCode  = errorCode;
    this.details    = details;

    // Capture a clean V8 stack trace that starts at the call site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /**
   * Serialise the error to a plain object suitable for a JSON response body.
   * Sensitive internals (stack trace) are intentionally excluded.
   */
  toJSON() {
    const payload = {
      error: {
        name:      this.name,
        code:      this.errorCode,
        message:   this.message,
        statusCode: this.statusCode,
      },
    };

    if (this.details !== null && this.details !== undefined) {
      payload.error.details = this.details;
    }

    return payload;
  }
}

// ---------------------------------------------------------------------------
// 404 – NotFoundError
// Thrown when a requested resource cannot be located.
//
// Usage:
//   throw new NotFoundError('User not found', { id: 42 });
// ---------------------------------------------------------------------------
class NotFoundError extends AppError {
  /**
   * @param {string}  [message='Resource not found']
   * @param {object}  [details=null] - e.g. the identifier that was looked up.
   */
  constructor(message = 'Resource not found', details = null) {
    super(message, 404, 'NOT_FOUND', details);
  }
}

// ---------------------------------------------------------------------------
// 422 – ValidationError
// Thrown when incoming data fails validation rules.
//
// Usage:
//   throw new ValidationError('Invalid request body', [
//     { field: 'email', message: 'Must be a valid email address' },
//   ]);
// ---------------------------------------------------------------------------
class ValidationError extends AppError {
  /**
   * @param {string}        [message='Validation failed']
   * @param {Array|object}  [details=null] - Per-field error list or summary.
   */
  constructor(message = 'Validation failed', details = null) {
    super(message, 422, 'VALIDATION_ERROR', details);
  }
}

// ---------------------------------------------------------------------------
// 503 – DatabaseError
// Thrown when a database operation fails (connection issues, query errors …).
// 503 signals that the service is temporarily unavailable so callers know to
// retry, while hiding internal DB details from the public response.
//
// Usage:
//   throw new DatabaseError('Could not fetch users', { operation: 'SELECT' });
// ---------------------------------------------------------------------------
class DatabaseError extends AppError {
  /**
