/**
 * errors.js
 *
 * Centralised custom error hierarchy for the application.
 *
 * All classes extend AppError, which itself extends the native Error so that:
 *   • instanceof checks work correctly throughout the stack.
 *   • Every error carries a consistent { statusCode, code, message } shape.
 *   • Express's centralised error handler can treat every thrown error
 *     uniformly without any per-route branching.
 *
 * Usage (in a route or service):
 *   throw new NotFoundError('User not found');
 *   throw new ValidationError('Email is required', [{ field: 'email', msg: '...' }]);
 *   throw new DatabaseError('Query failed');
 */

'use strict';

// ---------------------------------------------------------------------------
// Base class
// ---------------------------------------------------------------------------

/**
 * AppError
 *
 * Base class for all application-level errors.
 *
 * @param {string} message      - Human-readable description of the error.
 * @param {number} statusCode   - HTTP status code that should be sent to the client.
 * @param {string} code         - Machine-readable error code (e.g. 'NOT_FOUND').
 * @param {boolean} isOperational
 *   true  → the error is expected / safe to surface to the client.
 *   false → the error is a programming bug; the handler will mask the message.
 */
class AppError extends Error {
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Restore the correct prototype chain so `instanceof AppError` works even
    // after TypeScript / Babel transpilation.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name       = new.target.name; // e.g. "NotFoundError"
    this.statusCode = statusCode;
    this.code       = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call-site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, new.target);
    }
  }
}

// ---------------------------------------------------------------------------
// Concrete error classes
// ---------------------------------------------------------------------------

/**
 * NotFoundError  (404)
 *
 * Thrown when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User not found');
 *   throw new NotFoundError(`Post ${id} does not exist`);
 */
class NotFoundError extends AppError {
  constructor(message = 'Resource not found') {
    super(message, 404, 'NOT_FOUND');
  }
}

/**
 * ValidationError  (400)
 *
 * Thrown when incoming request data fails validation.
 *
 * @param {string}  message  - Summary of what went wrong.
 * @param {Array}   [errors] - Optional array of per-field validation details,
 *                             e.g. [{ field: 'email', message: 'Invalid format' }]
 *
 * @example
 *   throw new ValidationError('Request body is invalid', [
 *     { field: 'email', message: 'Must be a valid email address' },
 *     { field: 'age',   message: 'Must be a positive integer' },
 *   ]);
 */
class ValidationError extends AppError {
  constructor(message = 'Validation failed', errors = []) {
    super(message, 400, 'VALIDATION_ERROR');
    this.errors = errors; // expose per-field details
  }
}

/**
 * DatabaseError  (503)
 *
 * Thrown when a database operation fails unexpectedly.
 * Marked as non-operational so the error handler masks the raw message in
 * production, preventing internal details from leaking to clients.
 *
 * @example
 *   throw new DatabaseError('Connection pool exhausted');
 */
class DatabaseError extends AppError {
  constructor(message = 'A database error occurred') {
    // isOperational = false  →  the handler will not expose this message in production
    super(message, 503, 'DATABASE_ERROR', false);
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

/**
 * middleware/errorHandler.js
 *
 * Centralised Express error-handling middleware.
 *
 * Must be registered LAST in app.js (after all routes and other middleware)
 * so that every `next(err)` call and every `throw` inside an async route
 * reaches this single handler.
 *
 * Response shape
 * ──────────────
 * {
 *   "error": {
 *     "code":    "NOT_FOUND",          // machine-readable
 *     "message": "User not found",     // human-readable (may be masked in production)
 *     "errors":  [...]                 // present only for ValidationError
 *   }
 * }
 */

'use strict';

const { AppError, ValidationError } = require('../errors');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Determine whether the app is running in production mode.
 * We deliberately avoid trusting NODE_ENV alone; an explicit flag keeps
 * behaviour predictable regardless of how the process is started.
 */
const isProduction = () => process.env.NODE_ENV === 'production';

/**
 * Build a safe, client-facing error payload from any error object.
 *
 * - Operational AppErrors  → details are surfaced as-is.
 * - Non-operational errors → only a generic message is sent (in production)
 *   so that internal details (stack traces, DB messages) never reach clients.
 *
 * @param {Error}   err
 * @returns {{ statusCode: number, payload: object }}
 */
function buildErrorResponse(err) {
  // ── Known, operational application errors ──────────────────────────────
  if (err instanceof AppError && err.isOperational) {
    const payload = {
      error: {
        code:    err.code,
        message: err.message,
      },
    };

    // Attach per-field validation details when present
    if (err instanceof ValidationError && Array.isArray(err.errors) && err.errors.length > 0) {
      payload.error.errors = err.errors;
    }

    return { statusCode: err.statusCode, payload };
  }

  // ── Non-operational AppErrors (e.g. DatabaseError) ──────────────────────
  if (err instanceof AppError && !err.isOperational) {
    const message = isProduction()
      ? 'An unexpected error occurred. Please try again later.'
      : err.message; // expose real message in dev/test for easier debugging

    return {
      statusCode: err.statusCode,
      payload: {
        error: {
          code:    err.code,
          message,
        },
      },
    };
  }

  // ── Unknown / unhandled errors ──────────────────────────────────────────
  // Never leak raw details to the client in production.
  const message = isProduction()
    ? 'An internal server error occurred.'
    : err.message || 'Unknown error';

  return {
    statusCode: 500,
    payload: {
      error: {
        code:    'INTERNAL_SERVER_ERROR',
        message,
      },
    },
  };
}

// ---------------------------------------------------------------------------
// Middleware
// ---------------------------------------------------------------------------

/**
 * notFoundHandler
 *
 * Catch-all for routes that were never matched.
 * Register this BEFORE errorHandler but AFTER all valid routes.
 *
 * @type {import('express').RequestHandler}
 */
function notFoundHandler(req, res, next) {
  const { NotFoundError } = require('../errors'); // lazy require avoids circular dep
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`));
}

/**
 * errorHandler
 *
 * Central four-argument Express error middleware.
 * The unused `next` parameter MUST be kept; Express uses arity to detect
 * error-handling middleware.
 *
 * @type {import('express').ErrorRequestHandler}
 */
// eslint-disable-next-line no-unused-vars
function errorHandler(err, req, res, next) {
  const { statusCode, payload } = buildErrorResponse(err);

  // Always log the full error server-side for observability.
  // In production you would pipe this to your logging service.
  const logLevel = statusCode >= 500 ? 'error' : 'warn';
  console[logLevel](`[${new Date().toISOString()}] ${req.method} ${req.path} → ${statusCode}`, {
    code:    payload.error.code,
    message: err.message,        // log the real message regardless of env
    stack:   err.stack,
  });

  res.status(statusCode).json(payload);
}

module.exports = { notFoundHandler, errorHandler };

/**
 * routes/health.js
 *
 * Health-check endpoint.
 *
 * GET /health
 *   Returns 200 with basic liveness information.
 *   Throws a DatabaseError if an optional DB connectivity check fails,
 *   demonstrating how route-level errors propagate to the central handler.
 */

'use strict';

const express = require('express');
const { DatabaseError } = require('../errors');

const router = express.Router();

// ---------------------------------------------------------------------------
// Simulated dependency check
// (Replace with a real pool.query / ping in production)
// ---------------------------------------------------------------------------

/**
 * Lightweight stand-in for a real database connectivity check.
 * Resolves normally under test/dev; in production-like configs where
 * DB_CHECK_FAIL=true is set, it rejects to exercise the error path.
 *
 * @returns {Promise<void>}
 */
async function checkDatabaseConnection() {
  if (process.env.DB_CHECK_FAIL === 'true') {
    throw new Error('Connection refused');
  }
  // No-op in all other environments — real projects would `await pool.query('SELECT 1')`
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 *
 * Returns liveness status and an optional DB connectivity check.
 * On DB failure a DatabaseError is thrown and caught by the central handler,
 * which returns 503 without exposing the raw driver message.
 */
router.get('/', async (req, res, next) => {
  try {
    await checkDatabaseConnection();

    res.json({
      status:    'ok',
      timestamp: new Date().toISOString(),
      uptime:    process.uptime(),
    });
  } catch (err) {
    // Wrap low-level connectivity errors so the central handler can treat
    // them consistently (correct status code, masked message in production).
    if (!(err instanceof DatabaseError)) {
      return next(new DatabaseError('Database connectivity check failed'));
    }
    next(err);
  }
});

module.exports = router;

/**
 * routes/users.js
 *
 * User-resource endpoints.
 *
 * GET  /users        – list all users
 * GET  /users/:id    – fetch a single user by ID
 * POST /users        – create a new user
 *
 * Every error path uses `throw` (inside try/catch) or direct `next(err)` so
 * that all error responses flow through the single central error handler in
 * middleware/errorHandler.js.  No route contains an inline res.status().json()
 * for errors.
 */

'use strict';

const express = require('express');
const { NotFoundError, ValidationError, DatabaseError } = require('../errors');

const router = express.Router();

// ---------------------------------------------------------------------------
// In-memory "database"
// (Replace with real DB calls in production — error wrapping stays the same)
// ---------------------------------------------------------------------------

let users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

let nextId = 3;

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/**
 * Validate the fields required to create a user.
 * Returns an array of { field, message } objects; empty means valid.
 *
 * @param {object} body
 * @returns {{ field: string, message: string }[]}
 */
function validateUserBody(body) {
  const errs = [];

  if (!body.name || typeof body.name !== 'string' || body.name.trim() === '') {
    errs.push({ field: 'name', message: 'name is required and must be a non-empty string' });
  }

  if (!body.email || typeof body.email !== 'string') {
    errs.push({ field: 'email', message: 'email is required' });
  } else if (!EMAIL_RE.test(body.email.trim())) {
    errs.push({ field: 'email', message: 'email must be a valid email address' });
  } else if (users.some((u) => u.email.toLowerCase() === body.email.trim().toLowerCase())) {
    errs.push({ field: 'email', message: 'email is already in use' });
  }

  return errs;
}

// ---------------------------------------------------------------------------
// Simulated DB layer
// (Wrap real DB calls identically — throw DatabaseError on driver errors)
// ---------------------------------------------------------------------------

async function dbFindAll() {
  if (process.env.DB_FAIL === 'true') throw new Error('pool timeout');
  return users;
}

async function dbFindById(id) {
  if (process.env.DB_FAIL === 'true') throw new Error('pool timeout');
  return users.find((u) => u.id === id) || null;
}

async function dbCreate(data) {
  if (process.env.DB_FAIL === 'true') throw new Error('pool timeout');
  const user = { id: nextId++, name: data.name.trim(), email: data.email.trim().toLowerCase() };
  users.push(user);
  return user;
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /users
 *
 * Returns the full list of users.
 * Throws DatabaseError if the DB layer is unavailable.
 */
router.get('/', async (req, res, next) => {
  try {
    const data = await dbFindAll();
    res.json(data);
  } catch (err) {
    next(new DatabaseError('Failed to retrieve users'));
  }
});

/**
 * GET /users/:id
 *
 * Returns a single user identified by numeric :id.
 *
 * Throws:
 *   ValidationError – if :id is not a valid positive integer
 *   NotFoundError   – if no user with that ID exists
 *   DatabaseError   – if the DB layer is unavailable
 */
router.get('/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (!Number.isInteger(id) || id < 1) {
      throw new ValidationError('Invalid user ID', [
        { field: 'id', message: 'id must be a positive integer' },
      ]);
    }

    const user = await dbFindById(id);

    if (!user) {
      throw new NotFoundError(`User with id ${id} not found`);
    }

    res.json(user);
  } catch (err) {
    // Pass recognised AppErrors straight through; wrap anything else.
    if (err.isOperational !== undefined) return next(err);
    next(new DatabaseError('Failed to retrieve user'));
  }
});

/**
 * POST /users
 *
 * Creates a new user from { name, email } in the request body.
 *
 * Throws:
 *   ValidationError – if required fields are absent or malformed
 *   DatabaseError   – if the DB layer is unavailable
 */
router.post('/', async (req, res, next) => {
  try {
    const validationErrors = validateUserBody(req.body || {});

    if (validationErrors.length > 0) {
      throw new ValidationError('User validation failed', validationErrors);
    }

    const user = await dbCreate(req.body);

    res.status(201).json(user);
  } catch (err) {
    if (err.isOperational !== undefined) return next(err);
    next(new DatabaseError('Failed to create user'));
  }
});

module.exports = router;

/**
 * app.js
 *
 * Application entry point.
 *
 * Responsibilities:
 *   1. Create and configure the Express application.
 *   2. Register global middleware (body parsing, etc.).
 *   3. Mount route modules.
 *   4. Register the catch-all 404 handler.
 *   5. Register the centralised error handler (MUST be last).
 *   6. Start the HTTP server (only when run directly, not when imported by tests).
 *
 * Error flow
 * ──────────
 * Route  →  throw AppError (or next(err))
 *                │
 *                ▼
 *        notFoundHandler  (unmatched routes only)
 *                │
 *                ▼
 *          errorHandler   (all errors — formats & sends the response)
 */

'use strict';

const express = require('express');

const healthRouter              = require('./routes/health');
const usersRouter               = require('./routes/users');
const { notFoundHandler,
        errorHandler }          = require('./middleware/errorHandler');

const app  = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// Global middleware
// ---------------------------------------------------------------------------

// Parse JSON request bodies; returns 400 with a SyntaxError on malformed JSON
// — the central error handler recognises SyntaxError and returns a clean 400.
app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.use('/health', healthRouter);
app.use('/users',  usersRouter);

// ---------------------------------------------------------------------------
// Error handling  (order is significant — must come after all routes)
// ---------------------------------------------------------------------------

// 1. Catch unmatched routes and forward a NotFoundError to the error handler.
app.use(notFoundHandler);

// 2. Central error handler — formats every AppError (and unknown errors) into
//    a consistent JSON response.  The four-argument signature is required by
//    Express to recognise this as error-handling middleware.
app.use(errorHandler);

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

// Guard prevents the server from starting when the module is required by a
// test runner (e.g. supertest), keeping tests fast and port-conflict-free.
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

