assert.strictEqual(ve.code, 'VALIDATION_ERROR', 'VE code');
assert.strictEqual(ve.isOperational, true, 'VE isOperational');
assert.deepStrictEqual(ve.errors, [{ field: 'email', message: 'invalid' }], 'VE errors');
assert.ok(ve instanceof AppError, 'VE instanceof AppError');
assert.strictEqual(new ValidationError().message, 'Validation failed', 'VE default msg');
assert.deepStrictEqual(new ValidationError().errors, [], 'VE default errors');

