assert.strictEqual(de.statusCode, 503, 'DE statusCode');
assert.strictEqual(de.code, 'DATABASE_ERROR', 'DE code');
assert.strictEqual(de.isOperational, false, 'DE isOperational (non-operational)');
assert.ok(de instanceof AppError, 'DE instanceof AppError');
assert.strictEqual(new DatabaseError().message, 'A database error occurred', 'DE default msg');

// Prototype chain
assert.ok(new NotFoundError()   instanceof AppError, 'proto NotFoundError');
assert.ok(new ValidationError() instanceof AppError, 'proto ValidationError');
assert.ok(new DatabaseError()   instanceof AppError, 'proto DatabaseError');

console.log('[PASS] errors.js — all class assertions passed');

// ── 3. middleware/errorHandler.js ─────────────────────────────────────────
const { notFoundHandler, errorHandler } = require('./middleware/errorHandler');
assert.strictEqual(typeof notFoundHandler, 'function', 'notFoundHandler is a function');
