  assert.strictEqual(res._body.error.code, 'NOT_FOUND', 'handler: NotFoundError code');
  assert.strictEqual(res._body.error.message, 'nope', 'handler: NotFoundError message');
  assert.strictEqual(nextCalled, false, 'handler: did not call next');
