  const fields = [{ field: 'name', message: 'required' }];
  errorHandler(new ValidationError('invalid', fields), req, res, ()=>{});
  assert.strictEqual(res._status, 400, 'handler: ValidationError → 400');
  assert.deepStrictEqual(res._body.error.errors, fields, 'handler: ValidationError errors');
}

