  const req = mockReq(); const res = mockRes();
  errorHandler(new ValidationError('bad'), req, res, ()=>{});
  assert.strictEqual(res._status, 400, 'handler: ValidationError (no fields) → 400');
  assert.strictEqual(res._body.error.errors, undefined, 'handler: no errors key when empty');
