  const old = process.env.NODE_ENV;
  process.env.NODE_ENV = 'development';
  const req = mockReq(); const res = mockRes();
  errorHandler(new DatabaseError('pool timeout'), req, res, ()=>{});
  assert.strictEqual(res._status, 503, 'handler: DatabaseError → 503');
  assert.strictEqual(res._body.error.message, 'pool timeout', 'handler: DB msg in dev');
  process.env.NODE_ENV = old;
}

