  const old = process.env.NODE_ENV;
  process.env.NODE_ENV = 'production';
  const req = mockReq(); const res = mockRes();
  errorHandler(new DatabaseError('pool timeout'), req, res, ()=>{});
  assert.strictEqual(res._status, 503, 'handler: DatabaseError → 503 in prod');
  assert.notStrictEqual(res._body.error.message, 'pool timeout', 'handler: DB msg masked in prod');
  assert.ok(res._body.error.message.length > 0, 'handler: masked message not empty');
