}

// 3f. Unknown error (in dev) → 500 with real message
{
  const old = process.env.NODE_ENV;
  process.env.NODE_ENV = 'development';
  const req = mockReq(); const res = mockRes();
  errorHandler(new Error('boom'), req, res, ()=>{});
  assert.strictEqual(res._status, 500, 'handler: unknown error → 500');
  assert.strictEqual(res._body.error.code, 'INTERNAL_SERVER_ERROR', 'handler: unknown code');
  assert.strictEqual(res._body.error.message, 'boom', 'handler: unknown msg in dev');
  process.env.NODE_ENV = old;
}

// 3g. Unknown error in production → masked
{
  const old = process.env.NODE_ENV;
  process.env.NODE_ENV = 'production';
  const req = mockReq(); const res = mockRes();
  errorHandler(new Error('secret internals'), req, res, ()=>{});
  assert.strictEqual(res._status, 500, 'handler: unknown → 500 in prod');
  assert.notStrictEqual(res._body.error.message, 'secret internals', 'handler: masked in prod');
  process.env.NODE_ENV = old;
}

// 3h. notFoundHandler calls next with NotFoundError
{
  const req = mockReq('DELETE', '/no-such-route');
  let received = null;
  notFoundHandler(req, {}, (err) => { received = err; });
  assert.ok(received instanceof NotFoundError, 'notFoundHandler: throws NotFoundError');
  assert.ok(received.message.includes('DELETE'), 'notFoundHandler: includes method');
  assert.ok(received.message.includes('/no-such-route'), 'notFoundHandler: includes path');
}

console.log('[PASS] middleware/errorHandler.js — all handler assertions passed');

// ── 4. routes structural checks ───────────────────────────────────────────
// Require routes and confirm they export a Router-shaped object with expected routes.
const healthRouter = require('./routes/health');
const usersRouter  = require('./routes/users');

assert.ok(healthRouter && typeof healthRouter === 'object', 'health router exported');
assert.ok(usersRouter  && typeof usersRouter  === 'object', 'users router exported');

// Confirm expected HTTP verbs were registered on each router
const healthMethods = healthRouter._routes.map(r => r.method);
const usersMethods  = usersRouter._routes.map(r => r.method);

assert.ok(healthMethods.includes('get'), 'health: GET registered');
assert.ok(usersMethods.includes('get'),  'users: GET registered');
assert.ok(usersMethods.includes('post'), 'users: POST registered');

console.log('[PASS] routes/health.js + routes/users.js — structural checks passed');

// ── 5. app.js structural check ───────────────────────────────────────────
const app = require('./app');
// app.js uses app.use() to mount middleware and routers; verify something was registered
assert.ok(Array.isArray(appMock._middleware) && appMock._middleware.length >= 4,
  'app: at least 4 middleware/route registrations (json, health, users, errorHandler)');

// Confirm errorHandler (arity=4) is the LAST registered middleware
const last = appMock._middleware[appMock._middleware.length - 1];
const lastFn = Array.isArray(last) ? last[last.length - 1] : last;
assert.strictEqual(typeof lastFn, 'function', 'app: last middleware is a function');
assert.strictEqual(lastFn.length, 4, 'app: errorHandler (arity 4) is last');

console.log('[PASS] app.js — registration order checks passed');

console.log('');
console.log('══════════════════════════════════════════════');
console.log('  ALL TESTS PASSED');
console.log('══════════════════════════════════════════════');
