'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message     - Human-readable error description.
   * @param {number}  statusCode  - HTTP status code to send to the client.
   * @param {string}  code        - Machine-readable error code string.
   * @param {*}       [details]   - Optional structured details (e.g. field errors).
   */
  constructor(message, statusCode, code, details = null) {
    super(message);

    // Restore the correct prototype chain so `instanceof` checks work
    // even after TypeScript/Babel transpilation.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name       = this.constructor.name;
    this.statusCode = statusCode;
    this.code       = code;
    this.details    = details;

    // Capture a clean stack trace that omits this constructor frame.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 Not Found
// ---------------------------------------------------------------------------

class NotFoundError extends AppError {
  /**
   * Thrown when a requested resource does not exist.
   *
   * @param {string} [resource] - Name of the missing resource (e.g. "User").
   * @param {*}      [details]  - Optional extra context.
   *
   * @example
   *   throw new NotFoundError('User');
   *   // → 404  { code: 'NOT_FOUND', message: 'User not found.' }
   */
  constructor(resource = 'Resource', details = null) {
    super(`${resource} not found.`, 404, 'NOT_FOUND', details);
  }
