'use strict';

// ── Spin up the Express app and exercise every route ────────────────────
const app  = require('./app');
const http = require('http');

const server = http.createServer(app);
server.listen(0, '127.0.0.1', async () => {
  const { port } = server.address();
  const base = \`http://127.0.0.1:\${port}\`;

  // Helper — returns { status, body }
  async function req(method, path, payload) {
    const { default: fetch } = await import('node-fetch').catch(() => ({}));
    return new Promise((resolve, reject) => {
      const url = new URL(path, base);
      const data = payload ? JSON.stringify(payload) : null;
      const options = {
        hostname: url.hostname,
        port:     url.port,
        path:     url.pathname,
        method,
        headers: { 'Content-Type': 'application/json' },
      };
      const r = http.request(options, (res) => {
        let body = '';
        res.on('data', d => body += d);
        res.on('end', () => resolve({ status: res.statusCode, body: JSON.parse(body) }));
      });
      r.on('error', reject);
      if (data) r.write(data);
      r.end();
    });
  }

  const results = [];

  // 1. GET /health → 200
  let r = await req('GET', '/health');
  results.push({ test: 'GET /health → 200',
    pass: r.status === 200 && r.body.status === 'ok' });

  // 2. GET /users → 200 array
  r = await req('GET', '/users');
  results.push({ test: 'GET /users → 200 array',
    pass: r.status === 200 && Array.isArray(r.body) && r.body.length === 2 });

  // 3. GET /users/1 → 200 Alice
  r = await req('GET', '/users/1');
  results.push({ test: 'GET /users/1 → 200 Alice',
    pass: r.status === 200 && r.body.name === 'Alice' });

  // 4. GET /users/99 → 404 NOT_FOUND
  r = await req('GET', '/users/99');
  results.push({ test: 'GET /users/99 → 404 NOT_FOUND',
    pass: r.status === 404 && r.body.error.code === 'NOT_FOUND' });

  // 5. GET /users/abc → 422 VALIDATION_ERROR
  r = await req('GET', '/users/abc');
  results.push({ test: 'GET /users/abc → 422 VALIDATION_ERROR',
    pass: r.status === 422 && r.body.error.code === 'VALIDATION_ERROR'
       && r.body.error.details.id });

  // 6. POST /users valid → 201
  r = await req('POST', '/users', { name: 'Carol', email: 'carol@example.com' });
  results.push({ test: 'POST /users valid → 201',
    pass: r.status === 201 && r.body.name === 'Carol' });

  // 7. POST /users missing fields → 422 VALIDATION_ERROR with field details
  r = await req('POST', '/users', {});
  results.push({ test: 'POST /users missing → 422 VALIDATION_ERROR',
    pass: r.status === 422
       && r.body.error.code === 'VALIDATION_ERROR'
       && r.body.error.details.name
       && r.body.error.details.email });

  // 8. GET /nonexistent → 404 NOT_FOUND (catch-all)
  r = await req('GET', '/nonexistent');
  results.push({ test: 'GET /nonexistent → 404 catch-all',
    pass: r.status === 404 && r.body.error.code === 'NOT_FOUND' });

  // ── Print results ───────────────────────────────────────────────────────
  let allPassed = true;
  for (const { test, pass } of results) {
    console.log(\`  \${pass ? '✓' : '✗'} \${test}\`);
    if (!pass) allPassed = false;
  }
  console.log(allPassed ? '\nAll route tests passed ✓' : '\nSome tests FAILED ✗');

  server.close();
  process.exit(allPassed ? 0 : 1);
});
