// ── errors.js unit tests (no Express needed) ────────────────────────────────
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

let passed = 0, failed = 0;
function assert(cond, label) {
  if (cond) { console.log('  ✓', label); passed++; }
  else       { console.error('  ✗', label); failed++; }
}

// 1. AppError base
const base = new AppError('oops', 500, 'SOME_CODE', { hint: 'check logs' });
assert(base instanceof Error,    'AppError extends Error');
assert(base instanceof AppError, 'AppError instanceof AppError');
assert(base.statusCode === 500,  'AppError.statusCode');
assert(base.code === 'SOME_CODE','AppError.code');
assert(base.details.hint === 'check logs', 'AppError.details');
assert(base.name === 'AppError', 'AppError.name');
assert(typeof base.stack === 'string', 'AppError has stack trace');

// 2. NotFoundError
const nfe = new NotFoundError('Widget');
assert(nfe instanceof AppError,       'NotFoundError extends AppError');
assert(nfe instanceof NotFoundError,  'instanceof NotFoundError');
assert(nfe.statusCode === 404,        'NotFoundError.statusCode = 404');
assert(nfe.code === 'NOT_FOUND',      'NotFoundError.code');
assert(nfe.message === 'Widget not found.', 'NotFoundError.message');
assert(nfe.name === 'NotFoundError',  'NotFoundError.name');
assert(nfe.details === null,          'NotFoundError.details defaults to null');

// NotFoundError defaults
const nfe2 = new NotFoundError();
assert(nfe2.message === 'Resource not found.', 'NotFoundError default resource');

// 3. ValidationError
const ve = new ValidationError('Bad input', { field: 'required' });
assert(ve instanceof AppError,          'ValidationError extends AppError');
assert(ve instanceof ValidationError,   'instanceof ValidationError');
assert(ve.statusCode === 422,           'ValidationError.statusCode = 422');
assert(ve.code === 'VALIDATION_ERROR',  'ValidationError.code');
assert(ve.details.field === 'required', 'ValidationError.details.field');
assert(ve.name === 'ValidationError',   'ValidationError.name');

// ValidationError defaults
const ve2 = new ValidationError();
assert(ve2.message === 'Validation failed.', 'ValidationError default message');
assert(ve2.details === null,                 'ValidationError default details null');

// 4. DatabaseError
const de = new DatabaseError('Query failed', { table: 'users' });
assert(de instanceof AppError,        'DatabaseError extends AppError');
assert(de instanceof DatabaseError,   'instanceof DatabaseError');
assert(de.statusCode === 503,         'DatabaseError.statusCode = 503');
assert(de.code === 'DATABASE_ERROR',  'DatabaseError.code');
assert(de.details.table === 'users',  'DatabaseError.details.table');
assert(de.name === 'DatabaseError',   'DatabaseError.name');

// DatabaseError defaults
const de2 = new DatabaseError();
assert(de2.message === 'A database error occurred.', 'DatabaseError default message');

// 5. instanceof cross-checks (should NOT be true)
assert(!(nfe instanceof ValidationError), 'NotFoundError is NOT a ValidationError');
assert(!(ve  instanceof DatabaseError),   'ValidationError is NOT a DatabaseError');
assert(!(de  instanceof NotFoundError),   'DatabaseError is NOT a NotFoundError');

// 6. Error.captureStackTrace was called — constructor frame should NOT appear
const frames = nfe.stack.split('\n');
const hasCtorFrame = frames.some(f => f.includes('AppError') && f.includes('new AppError'));
assert(!hasCtorFrame, 'Constructor frame stripped from stack trace');

console.log(\`\nResult: \${passed} passed, \${failed} failed\`);
process.exit(failed > 0 ? 1 : 0);
