    super(`${resource} not found.`, 404, 'NOT_FOUND', details);
  }
}

// ---------------------------------------------------------------------------
// 422 Validation Error
// ---------------------------------------------------------------------------

class ValidationError extends AppError {
  /**
   * Thrown when request input fails validation.
   *
   * @param {string}                    [message] - Summary of what is invalid.
   * @param {Record<string, string>}    [fields]  - Per-field validation messages.
   *
   * @example
   *   throw new ValidationError('Invalid request body.', { email: 'Must be a valid e-mail.' });
   *   // → 422  { code: 'VALIDATION_ERROR', message: '...', details: { email: '...' } }
   */
  constructor(message = 'Validation failed.', fields = null) {
    super(message, 422, 'VALIDATION_ERROR', fields);
  }
}

// ---------------------------------------------------------------------------
// 503 Database Error
// ---------------------------------------------------------------------------

class DatabaseError extends AppError {
  /**
   * Thrown when a database operation fails unexpectedly.
   *
   * @param {string} [message]  - Description of the failure.
   * @param {*}      [details]  - Optional extra context (query, table name, …).
   *
   * @example
   *   throw new DatabaseError('Failed to fetch users.');
   *   // → 503  { code: 'DATABASE_ERROR', message: 'Failed to fetch users.' }
   */
  constructor(message = 'A database error occurred.', details = null) {
    super(message, 503, 'DATABASE_ERROR', details);
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Route handlers
// ---------------------------------------------------------------------------

// GET /health — liveness probe; no error path needed.
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users — returns all users.
// Demonstrates: throwing a DatabaseError when the data layer fails.
app.get('/users', (req, res) => {
  // In a real app this would be an async DB call.  Any rejection/throw from
  // that call should be a DatabaseError so the middleware maps it correctly.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  res.json(users);
});

// GET /users/:id — fetch a single user by numeric id.
// Demonstrates: ValidationError for a bad id param, NotFoundError when the
// user doesn't exist.
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Invalid user id.', {
      id: 'Must be a positive integer.',
    });
  }

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  const user = users.find((u) => u.id === id);
  if (!user) {
    throw new NotFoundError('User');
  }

  res.json(user);
});

// POST /users — create a new user.
// Demonstrates: ValidationError when required fields are missing or malformed.
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};
  const fieldErrors = {};

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.name = 'Name is required and must be a non-empty string.';
  }

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!email || !emailRegex.test(email)) {
    fieldErrors.email = 'A valid e-mail address is required.';
  }

  if (Object.keys(fieldErrors).length > 0) {
    throw new ValidationError('Invalid request body.', fieldErrors);
  }

  // Simulate persisting and returning the created resource.
  const created = { id: 3, name: name.trim(), email };
  res.status(201).json(created);
});

// ---------------------------------------------------------------------------
// 404 catch-all — must be registered AFTER all real routes.
// ---------------------------------------------------------------------------

app.use((req, res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.path}`));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
//
// Express identifies error-handling middleware by its four-argument signature
// (err, req, res, next).  It must be the LAST middleware registered.
// ---------------------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── 1. Determine status code ──────────────────────────────────────────────
  // Prefer the statusCode carried by our AppError subclasses; fall back to
  // whatever was set on a generic Error (e.g. http-errors), then default to
  // 500 for truly unexpected errors.
  const statusCode = err.statusCode ?? err.status ?? 500;

  // ── 2. Build a consistent error envelope ─────────────────────────────────
  const body = {
    error: {
      code:    err.code    ?? 'INTERNAL_ERROR',
      message: err.message ?? 'An unexpected error occurred.',
      // Only include `details` when the error actually carries extra context
      // (avoids sending a null key for simple errors).
      ...(err.details != null && { details: err.details }),
    },
  };

  // ── 3. Log unexpected errors server-side ─────────────────────────────────
  // Log the full stack for anything that isn't one of our known AppErrors so
  // developers can diagnose truly unexpected failures.  Known operational
  // errors (4xx / 503) are intentional and don't need a stack trace in logs.
  if (!(err instanceof AppError)) {
    console.error('[Unhandled error]', err);
  }

  // ── 4. Send the response ──────────────────────────────────────────────────
  res.status(statusCode).json(body);
});

// ---------------------------------------------------------------------------
// Start server (skipped when the module is required by tests)
// ---------------------------------------------------------------------------

if (require.main === module) {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

