/**
 * errors.js
 *
 * Centralised application error classes.
 *
 * Every class extends the base AppError so that the error-handling middleware
 * can distinguish "known, safe-to-expose" errors from unexpected ones with a
 * single instanceof check.
 *
 * Usage (inside a route or service):
 *
 *   const { NotFoundError, ValidationError, DatabaseError } = require('./errors');
 *
 *   throw new NotFoundError('User not found');
 *   throw new ValidationError('email is required', { field: 'email' });
 *   throw new DatabaseError('Connection refused');
 */

'use strict';

// ─── Base class ──────────────────────────────────────────────────────────────

/**
 * AppError
 *
 * All application-level errors inherit from this class.
 *
 * @property {number}  statusCode  - HTTP status code sent to the client.
 * @property {string}  code        - Machine-readable error code (e.g. "NOT_FOUND").
 * @property {boolean} isOperational - true  → known error, safe to expose details.
 *                                     false → programmer error, hide internals.
 * @property {*}       details     - Optional structured payload (field errors, etc.).
 */
class AppError extends Error {
  /**
   * @param {string} message      - Human-readable description.
   * @param {number} statusCode   - HTTP status code.
   * @param {string} code         - Machine-readable identifier.
   * @param {*}      [details]    - Extra structured information.
   */
  constructor(message, statusCode, code, details = null) {
    super(message);

    // Restore the prototype chain so that `instanceof AppError` works correctly
    // even after transpilation (TypeScript / Babel).
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.code        = code;
    this.details     = details;
    this.isOperational = true;

    // Capture a clean stack trace that starts at the call-site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /**
   * Serialise the error to the JSON shape returned to API consumers.
   *
   * @returns {{ error: { code: string, message: string, details: * } }}
   */
  toJSON() {
    const payload = {
      error: {
        code:    this.code,
        message: this.message,
      },
    };

    if (this.details !== null && this.details !== undefined) {
      payload.error.details = this.details;
    }

    return payload;
  }
}

// ─── Concrete error classes ───────────────────────────────────────────────────

/**
 * NotFoundError  (HTTP 404)
 *
 * Raised when a requested resource does not exist.
 *
 * @example
 *   throw new NotFoundError('User with id 42 not found');
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message]  - Defaults to "Resource not found".
   * @param {*}      [details]  - Optional extra context.
   */
  constructor(message = 'Resource not found', details = null) {
    super(message, 404, 'NOT_FOUND', details);
  }
}

/**
 * ValidationError  (HTTP 422)
 *
 * Raised when request input fails validation.
 * Pass a `details` object or array so consumers know exactly which fields
 * failed and why.
 *
 * @example
 *   throw new ValidationError('Invalid request body', [
 *     { field: 'email', message: 'must be a valid email address' },
 *     { field: 'age',   message: 'must be a positive integer' },
 *   ]);
 */
class ValidationError extends AppError {
  /**
   * @param {string} [message]  - Defaults to "Validation failed".
   * @param {*}      [details]  - Field-level validation errors.
   */
  constructor(message = 'Validation failed', details = null) {
    super(message, 422, 'VALIDATION_ERROR', details);
  }
}

/**
 * DatabaseError  (HTTP 503)
 *
 * Raised when a database operation fails (connection error, query error, etc.).
 * The original low-level cause can be passed as `details` for internal logging,
 * but the middleware will sanitise what is sent to the client.
 *
 * @example
 *   throw new DatabaseError('Failed to fetch user record', originalError.message);
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message]  - Defaults to "A database error occurred".
   * @param {*}      [details]  - Internal diagnostic info (logged, not exposed).
   */
  constructor(message = 'A database error occurred', details = null) {
    super(message, 503, 'DATABASE_ERROR', details);
  }
}

// ─── Exports ─────────────────────────────────────────────────────────────────

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

'use strict';

/**
 * app.js
 *
 * Express application with centralised error handling.
 *
 * Error flow
 * ──────────
 * Routes / middleware throw (or call next(err) with) an AppError subclass.
 * The single errorHandler middleware at the bottom converts every error into
 * a consistent JSON response, distinguishing operational errors (safe to
 * expose) from unexpected programmer errors (internals are hidden).
 */

const express = require('express');

const {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
} = require('./errors');

const app = express();

// ─── Body parsing ─────────────────────────────────────────────────────────────
app.use(express.json());

// ─── Routes ──────────────────────────────────────────────────────────────────

/**
 * GET /health
 *
 * Simple liveness probe — no domain logic, never throws.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 *
 * Returns the list of all users.
 * Demonstrates: no error path needed here; a real DB call would throw
 * DatabaseError on failure (see /users/:id for the pattern).
 */
app.get('/users', (req, res) => {
  // In a real app this would be: const users = await UserService.findAll();
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  res.json(users);
});

/**
 * GET /users/:id
 *
 * Returns a single user by numeric id.
 * Demonstrates:
 *   - ValidationError  → id is not a positive integer.
 *   - NotFoundError    → id is valid but no matching record exists.
 *   - DatabaseError    → storage layer is unavailable (simulated).
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  // ── Validation ────────────────────────────────────────────────────────────
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('User id must be a positive integer', {
      field:   'id',
      received: req.params.id,
    });
  }

  // ── Simulated data store ──────────────────────────────────────────────────
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  // Simulate an intermittent database failure for id === 999 so the
  // DatabaseError path can be exercised in tests.
  if (id === 999) {
    throw new DatabaseError(
      'Failed to query user record',
      'Connection timeout after 5 000 ms',   // internal detail, logged not exposed
    );
  }

  // ── Not found ─────────────────────────────────────────────────────────────
  const user = users.find((u) => u.id === id);
  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`);
  }

  res.json(user);
});

/**
 * POST /users
 *
 * Creates a new user.
 * Demonstrates ValidationError for missing / malformed fields.
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};

  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'name is required and must be a non-empty string' });
  }

  if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    fieldErrors.push({ field: 'email', message: 'email is required and must be a valid address' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Invalid request body', fieldErrors);
  }

  // In a real app: const created = await UserService.create({ name, email });
  const created = { id: 3, name: name.trim(), email };
  res.status(201).json(created);
});

// ─── 404 catch-all ────────────────────────────────────────────────────────────
// Must be registered AFTER all valid routes so it only fires for truly unknown
// paths.  Throws a NotFoundError so it passes through the same error handler.
app.use((req, _res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`));
});

// ─── Centralised error handler ───────────────────────────────────────────────
/**
 * errorHandler
 *
 * Single Express error-handling middleware (4-argument signature).
 *
 * Behaviour
 * ─────────
 * • AppError subclasses (isOperational === true):
 *     Use the error's own statusCode and expose message + code + details.
 *
 * • DatabaseError specifically:
 *     Uses 503 and omits internal `details` from the client response to avoid
 *     leaking connection strings, stack traces, or query internals.
 *
 * • Everything else (programmer errors, missing modules, etc.):
 *     Returns 500 with a generic message; full error is only logged server-side.
 *
 * @param {Error}           err
 * @param {express.Request} req
 * @param {express.Response} res
 * @param {express.NextFunction} next  - Must be declared even if unused so that
 *                                       Express recognises this as an error handler.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, _res, next) => {
  const res = _res; // alias for clarity inside the function

  // ── Always log the full error server-side ────────────────────────────────
  console.error({
    message:    err.message,
    code:       err.code     ?? 'UNKNOWN',
    statusCode: err.statusCode ?? 500,
    stack:      err.stack,
    details:    err.details  ?? null,
    path:       req.path,
    method:     req.method,
  });

  // ── Operational error (one of our AppError subclasses) ───────────────────
  if (err instanceof AppError) {
    const body = err.toJSON();

    // DatabaseError: strip internal details before sending to the client.
    if (err instanceof DatabaseError) {
      delete body.error.details;
    }

    return res.status(err.statusCode).json(body);
  }

  // ── Unexpected / programmer error ────────────────────────────────────────
  // Do not leak any internals; return a generic 500.
  return res.status(500).json({
    error: {
      code:    'INTERNAL_SERVER_ERROR',
      message: 'An unexpected error occurred. Please try again later.',
    },
  });
});

// ─── Start ───────────────────────────────────────────────────────────────────
/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT ?? 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

{
  "name": "express-centralised-errors",
  "version": "1.0.0",
  "description": "Express app with centralised error handling",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "jest --verbose"
  },
  "dependencies": {
    "express": "^4.18.2"
  },
  "devDependencies": {
    "jest": "^29.7.0",
    "supertest": "^6.3.4"
  }
}

