/**
 * errors.js
 * ---------
 * Centralised error class hierarchy for the Express application.
 *
 * Usage
 * -----
 *   const { NotFoundError, ValidationError, DatabaseError } = require('./errors');
 *
 *   // In a route or service:
 *   throw new NotFoundError('User not found');
 *   throw new ValidationError('Email is required', [{ field: 'email', message: 'required' }]);
 *   throw new DatabaseError('Query failed');
 *
 * All classes extend AppError, which itself extends the native Error so that
 * `instanceof Error` checks and stack traces continue to work correctly.
 */

'use strict';

// ---------------------------------------------------------------------------
// Base class
// ---------------------------------------------------------------------------

/**
 * AppError
 *
 * Base class for all application-level errors.  Never throw this directly —
 * use one of the concrete subclasses below so that the error handler can
 * distinguish between error categories.
 *
 * @property {number}  statusCode - HTTP status code sent to the client.
 * @property {string}  code       - Machine-readable error code string.
 * @property {boolean} isOperational
 *   true  → predictable, user-facing error (safe to surface in the response).
 *   false → unexpected programmer error (should trigger an alert / 500).
 */
class AppError extends Error {
  /**
   * @param {string}  message       - Human-readable description of the error.
   * @param {number}  statusCode    - HTTP status code (default 500).
   * @param {string}  code          - Snake-case machine-readable code.
   * @param {boolean} isOperational - Whether this is an expected runtime error.
   */
  constructor(message, statusCode = 500, code = 'INTERNAL_ERROR', isOperational = true) {
    super(message);

    // Restore the correct prototype chain so `instanceof` works after
    // TypeScript / Babel transpilation (no-op in plain Node, but harmless).
    Object.setPrototypeOf(this, new.target.prototype);

    this.name       = this.constructor.name;
    this.statusCode = statusCode;
    this.code       = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call-site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /**
   * Returns a plain object suitable for JSON serialisation in an API response.
   * Sensitive internal details (stack trace, etc.) are never included.
   *
   * @returns {{ error: { code: string, message: string, statusCode: number } }}
   */
  toJSON() {
    return {
      error: {
        code:       this.code,
        message:    this.message,
        statusCode: this.statusCode,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 404 – Not Found
// ---------------------------------------------------------------------------

/**
 * NotFoundError
 *
 * Thrown when a requested resource does not exist.
 *
 * HTTP status : 404 Not Found
 * Code        : NOT_FOUND
 *
 * @example
 *   throw new NotFoundError('User with id 42 not found');
 *   throw new NotFoundError(); // uses default message
 */
class NotFoundError extends AppError {
  /**
   * @param {string} message   - Optional override for the default message.
   * @param {string} resource  - Optional name of the missing resource type
   *                             (e.g. 'User', 'Order').  Included in toJSON()
   *                             when provided so clients can act on it.
   */
  constructor(message = 'The requested resource was not found', resource = null) {
    super(message, 404, 'NOT_FOUND', true);
    if (resource) {
      this.resource = resource;
    }
  }

  toJSON() {
    const base = super.toJSON();
    if (this.resource) {
      base.error.resource = this.resource;
    }
    return base;
  }
}

// ---------------------------------------------------------------------------
// 422 – Validation Error
// ---------------------------------------------------------------------------

/**
 * ValidationError
 *
 * Thrown when incoming request data fails validation rules.
 *
 * HTTP status : 422 Unprocessable Entity
 * Code        : VALIDATION_ERROR
 *
 * @example
 *   throw new ValidationError('Invalid request body');
 *
 *   throw new ValidationError('Request validation failed', [
 *     { field: 'email',    message: 'Must be a valid email address' },
 *     { field: 'password', message: 'Must be at least 8 characters' },
 *   ]);
 */
class ValidationError extends AppError {
  /**
   * @param {string}   message - Human-readable summary of the validation failure.
   * @param {Array<{ field: string, message: string }>} [fieldErrors=[]]
   *   Per-field validation messages.  Defaults to an empty array so callers
   *   that only have a top-level message do not need to supply the argument.
   */
  constructor(message = 'Validation failed', fieldErrors = []) {
    super(message, 422, 'VALIDATION_ERROR', true);

    if (!Array.isArray(fieldErrors)) {
      throw new TypeError('ValidationError: fieldErrors must be an array');
    }
    this.fieldErrors = fieldErrors;
  }

  toJSON() {
    const base = super.toJSON();
    if (this.fieldErrors.length > 0) {
      base.error.fieldErrors = this.fieldErrors;
    }
    return base;
  }
}

// ---------------------------------------------------------------------------
// 503 – Database Error
// ---------------------------------------------------------------------------

/**
 * DatabaseError
 *
 * Thrown when a database operation fails in a way that should surface as a
 * service-level error.  Marked as non-operational (isOperational = false)
 * because it typically signals infrastructure problems rather than bad
 * user input; the error handler will treat it as a 503.
 *
 * HTTP status : 503 Service Unavailable
 * Code        : DATABASE_ERROR
 *
 * @example
 *   throw new DatabaseError('Failed to connect to the database');
 *   throw new DatabaseError('Query timed out', originalError);
 */
class DatabaseError extends AppError {
  /**
   * @param {string} message         - Human-readable description of the failure.
   * @param {Error}  [originalError] - The underlying driver/ORM error, stored
   *                                   privately so it can be logged without
   *                                   being leaked to the client.
   */
  constructor(message = 'A database error occurred', originalError = null) {
    // isOperational = false → treated as unexpected; triggers 503
    super(message, 503, 'DATABASE_ERROR', false);

    if (originalError instanceof Error) {
      // Keep the original error for server-side logging only.
      // It is deliberately excluded from toJSON() to prevent leaking
      // internal query details or connection strings to the client.
      this.originalError = originalError;
    }
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

/**
 * app.js
 * ------
 * Express application entry point.
 *
 * Error handling strategy
 * -----------------------
 * Routes never call res.status().json() for error cases directly.  Instead
 * they throw (synchronous routes) or call next(err) (async routes) with one
 * of the typed error classes from errors.js.  A single centralised error
 * handler at the bottom of the middleware stack is the only place that writes
 * error responses, keeping that logic in one place and keeping routes clean.
 *
 *   Operational errors (NotFoundError, ValidationError)
 *     → logged at "warn" level, status + code forwarded to the client.
 *
 *   Non-operational errors (DatabaseError, unexpected throws)
 *     → logged at "error" level, generic 500/503 message sent to the client
 *       so that internal details are never leaked.
 */

'use strict';

const express = require('express');
const { NotFoundError, ValidationError, DatabaseError, AppError } = require('./errors');

const app = express();

app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Returns a simple liveness signal.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns all users.
 *
 * Throws DatabaseError if the data layer is unavailable.
 */
app.get('/users', (req, res, next) => {
  try {
    // --- data-access simulation ------------------------------------------
    // Replace the block below with a real DB call.  If that call throws,
    // wrap it in a DatabaseError before re-throwing so the error handler
    // can classify it correctly.
    // -----------------------------------------------------------------------
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];
    // -----------------------------------------------------------------------

    res.json(users);
  } catch (err) {
    // Re-wrap unexpected DB/driver errors so they get the right status code.
    next(err instanceof AppError ? err : new DatabaseError('Failed to retrieve users', err));
  }
});

/**
 * GET /users/:id
 * Returns a single user by numeric id.
 *
 * Throws ValidationError when :id is not a positive integer.
 * Throws NotFoundError   when no user matches the given id.
 */
app.get('/users/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);

    // --- input validation --------------------------------------------------
    if (!Number.isInteger(id) || id <= 0) {
      throw new ValidationError('User id must be a positive integer', [
        { field: 'id', message: 'Must be a positive integer' },
      ]);
    }
    // -----------------------------------------------------------------------

    // --- data-access simulation --------------------------------------------
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    const user = users.find((u) => u.id === id);
    // -----------------------------------------------------------------------

    if (!user) {
      throw new NotFoundError(`User with id ${id} not found`, 'User');
    }

    res.json(user);
  } catch (err) {
    next(err instanceof AppError ? err : new DatabaseError('Failed to retrieve user', err));
  }
});

/**
 * POST /users
 * Creates a new user.
 *
 * Throws ValidationError when required fields are missing or malformed.
 * Throws DatabaseError   when the insert operation fails.
 */
app.post('/users', (req, res, next) => {
  try {
    const { name, email } = req.body ?? {};

    // --- input validation --------------------------------------------------
    const fieldErrors = [];

    if (!name || typeof name !== 'string' || name.trim() === '') {
      fieldErrors.push({ field: 'name', message: 'Name is required and must be a non-empty string' });
    }

    if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      fieldErrors.push({ field: 'email', message: 'A valid email address is required' });
    }

    if (fieldErrors.length > 0) {
      throw new ValidationError('Request validation failed', fieldErrors);
    }
    // -----------------------------------------------------------------------

    // --- data-access simulation --------------------------------------------
    // Replace with a real INSERT and return the persisted record.
    const newUser = { id: 3, name: name.trim(), email: email.trim() };
    // -----------------------------------------------------------------------

    res.status(201).json(newUser);
  } catch (err) {
    next(err instanceof AppError ? err : new DatabaseError('Failed to create user', err));
  }
});

// ---------------------------------------------------------------------------
// 404 catch-all  (must come AFTER all routes)
// ---------------------------------------------------------------------------

/**
 * Any request that falls through all defined routes hits this handler, which
 * normalises it into a NotFoundError and passes it to the error handler below.
 */
app.use((req, res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`));
});

// ---------------------------------------------------------------------------
// Centralised error handling middleware
// ---------------------------------------------------------------------------

/**
 * errorHandler
 * ------------
 * Single, authoritative place where errors are converted into HTTP responses.
 *
 * Express recognises a four-argument middleware as an error handler.  It is
 * invoked whenever next(err) is called anywhere in the stack.
 *
 * Behaviour
 * ---------
 *  • Operational AppErrors  → status from the error, safe message, error code.
 *  • Non-operational AppErrors / unexpected throws
 *                           → 500 (or the error's own status), generic message.
 *  • The original error (including stack trace) is always logged server-side
 *    so nothing is silently swallowed.
 *
 * @param {Error}            err  - The thrown/passed error.
 * @param {express.Request}  req  - Incoming request (used for log context).
 * @param {express.Response} res  - Outgoing response.
 * @param {express.NextFunction} next - Required by Express even if unused.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ------------------------------------------------------------------
  // 1. Determine whether this is a known, operational error.
  // ------------------------------------------------------------------
  const isOperational = err instanceof AppError && err.isOperational;

  // ------------------------------------------------------------------
  // 2. Resolve the HTTP status code.
  //    • AppError subclasses carry their own statusCode.
  //    • Unknown errors always become 500.
  // ------------------------------------------------------------------
  const statusCode = err instanceof AppError ? err.statusCode : 500;

  // ------------------------------------------------------------------
  // 3. Log the error with appropriate severity.
  //    • Operational errors (bad input, missing resources) → warn.
  //    • Everything else (bugs, infra failures)            → error.
  //
  //    console.warn / console.error write to stderr in Node, which is
  //    sufficient for a standard setup.  Swap these for your logger
  //    (e.g. winston, pino) without changing anything else.
  // ------------------------------------------------------------------
  const logPayload = {
    method:     req.method,
    path:       req.path,
    statusCode,
    code:       err.code    ?? 'UNKNOWN_ERROR',
    message:    err.message ?? 'An unexpected error occurred',
    stack:      err.stack,
    // Include the underlying cause for DatabaseErrors
    ...(err.originalError && { originalError: err.originalError.message }),
  };

  if (isOperational) {
    console.warn('[warn] Operational error:', logPayload);
  } else {
    console.error('[error] Unexpected error:', logPayload);
  }

  // ------------------------------------------------------------------
  // 4. Build the client-facing response.
  //    Operational errors expose their own message and code.
  //    Non-operational errors always return a generic message so that
  //    internal details (query strings, file paths, etc.) are never
  //    leaked to the client.
  // ------------------------------------------------------------------
  if (isOperational) {
    // AppError.toJSON() already shapes the body correctly.
    return res.status(statusCode).json(err.toJSON());
  }

  // Generic response for unexpected / non-operational errors.
  return res.status(statusCode).json({
    error: {
      code:       'INTERNAL_ERROR',
      message:    'An unexpected error occurred. Please try again later.',
      statusCode,
    },
  });
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT ?? 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

