/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Every class extends the base AppError, which carries:
 *  - message   – human-readable description
 *  - statusCode – HTTP status code sent to the client
 *  - code       – machine-readable error code for client-side handling
 *  - isOperational – distinguishes expected errors (true) from bugs (false)
 */

'use strict';

// ---------------------------------------------------------------------------
// Base error
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string} message       Human-readable error description.
   * @param {number} statusCode    HTTP status code (e.g. 404, 422, 500).
   * @param {string} code          Machine-readable snake_case code.
   * @param {boolean} isOperational True for expected errors, false for bugs.
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Maintains proper prototype chain for `instanceof` checks.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name       = this.constructor.name;
    this.statusCode = statusCode;
    this.code       = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 – Not Found
// ---------------------------------------------------------------------------

/**
 * Thrown when a requested resource does not exist.
 *
 * @example
 *   throw new NotFoundError('User not found', 'user');
 *   // { statusCode: 404, code: 'USER_NOT_FOUND' }
 */
class NotFoundError extends AppError {
  /**
   * @param {string} message      Description of what was not found.
   * @param {string} [resource]   Optional resource name used to build `code`
   *                              (e.g. 'user' → 'USER_NOT_FOUND').
   *                              Defaults to the generic code 'NOT_FOUND'.
   */
  constructor(message, resource) {
    const code = resource
      ? `${resource.toUpperCase()}_NOT_FOUND`
      : 'NOT_FOUND';

    super(message, 404, code);
  }
}

// ---------------------------------------------------------------------------
// 422 – Validation Error
// ---------------------------------------------------------------------------

/**
 * Thrown when request input fails validation.
 * Carries an optional `fields` map so callers can highlight specific inputs.
 *
 * @example
 *   throw new ValidationError('Invalid request body', {
 *     email: 'Must be a valid e-mail address',
 *     age:   'Must be a positive integer',
 *   });
 */
class ValidationError extends AppError {
  /**
   * @param {string} message                       Summary of what is invalid.
   * @param {Object.<string, string>} [fields={}]  Per-field error messages.
   */
  constructor(message, fields = {}) {
    super(message, 422, 'VALIDATION_ERROR');
    this.fields = fields;
  }
}

// ---------------------------------------------------------------------------
// 503 – Database Error
// ---------------------------------------------------------------------------

/**
