/**
 * errors.js
 *
 * Centralised custom error classes for the application.
 *
 * Every class extends the built-in Error and adds two extra fields that the
 * Express error-handling middleware reads:
 *
 *   statusCode  – the HTTP status code to send to the client
 *   isOperational – true  → known, expected error (safe to expose details)
 *                   false → programmer error (hide details in production)
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message       - Human-readable description of the error.
   * @param {number}  statusCode    - HTTP status code (default 500).
   * @param {string}  [code]        - Machine-readable error code (e.g. "NOT_FOUND").
   * @param {boolean} [isOperational=true] - Whether this is an expected,
   *                                         operational error or a programmer bug.
   */
  constructor(message, statusCode = 500, code = 'INTERNAL_ERROR', isOperational = true) {
    super(message);

    // Keep the prototype chain intact so `instanceof` works correctly after
    // TypeScript / Babel transpilation and in plain Node as well.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name       = new.target.name; // e.g. "NotFoundError"
    this.statusCode = statusCode;
    this.code       = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call-site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, new.target);
    }
  }

  /** Serialise the error into the shape the API sends to clients. */
  toJSON() {
    return {
      error: {
        code:    this.code,
        message: this.message,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 404 Not Found
// ---------------------------------------------------------------------------

/**
 * Thrown when a requested resource does not exist.
 *
 * @example
 *   throw new NotFoundError('User not found', 'USER_NOT_FOUND');
 *   throw new NotFoundError(`Product ${id} not found`);
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message]  - Defaults to "Resource not found".
   * @param {string} [code]     - Defaults to "NOT_FOUND".
   */
  constructor(message = 'Resource not found', code = 'NOT_FOUND') {
    super(message, 404, code);
  }
}

// ---------------------------------------------------------------------------
// 422 Unprocessable Entity — Validation
// ---------------------------------------------------------------------------

/**
 * Thrown when request input fails business-rule or schema validation.
 *
 * An optional `fields` map can carry per-field error messages that the client
 * can use to highlight individual form controls.
 *
 * @example
 *   throw new ValidationError('Invalid email address');
 *   throw new ValidationError('Validation failed', {
 *     email: 'Must be a valid e-mail address',
 *     age:   'Must be a positive integer',
 *   });
 */
class ValidationError extends AppError {
  /**
   * @param {string} [message]           - Defaults to "Validation failed".
   * @param {Object} [fields={}]         - Map of { fieldName: errorMessage }.
   * @param {string} [code]              - Defaults to "VALIDATION_ERROR".
   */
  constructor(message = 'Validation failed', fields = {}, code = 'VALIDATION_ERROR') {
    super(message, 422, code);
    this.fields = fields; // e.g. { email: 'Invalid format', name: 'Required' }
  }

  toJSON() {
    return {
      error: {
        code:    this.code,
        message: this.message,
        // Only include `fields` key when there is at least one field error so
        // the response stays clean for simple single-message validation errors.
        ...(Object.keys(this.fields).length > 0 && { fields: this.fields }),
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 503 Service Unavailable — Database
// ---------------------------------------------------------------------------

/**
 * Thrown when a database operation fails (connection error, query timeout,
 * constraint violation that should not be exposed as a validation error, etc.).
 *
 * The original `cause` is stored but intentionally NOT forwarded to the client
 * because it may contain sensitive schema information.
 *
 * @example
 *   try {
 *     await db.query(...);
 *   } catch (cause) {
 *     throw new DatabaseError('Could not fetch users', cause);
 *   }
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message]  - Defaults to "Database operation failed".
   * @param {Error}  [cause]    - The original low-level error (kept server-side only).
   * @param {string} [code]     - Defaults to "DATABASE_ERROR".
   */
  constructor(message = 'Database operation failed', cause = null, code = 'DATABASE_ERROR') {
    // isOperational = true so that the error handler knows this is an
    // anticipated failure, but we still respond with 503 so monitoring
    // systems can distinguish DB problems from 4xx client errors.
    super(message, 503, code, true);
    this.cause = cause; // Available for server-side logging; never sent to client.
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

'use strict';

/**
 * app.js
 *
 * Express application with:
 *   • Route handlers that throw custom errors instead of inlining res.status().json()
 *   • A single centralised error-handling middleware that translates every
 *     thrown error into a consistent JSON response
