/**
 * POST /users
 * Creates a new user.
 *
 * Demonstrates ValidationError with multiple field-level messages.
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};
  const fieldErrors = {};

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.name = 'Name is required and must be a non-empty string';
  }

  // Very simple e-mail sanity check — swap in a proper validator in production
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!email || !emailRegex.test(email)) {
    fieldErrors.email = 'A valid e-mail address is required';
  }

  if (Object.keys(fieldErrors).length > 0) {
    throw new ValidationError('User creation failed due to invalid input', fieldErrors);
  }

  // Simulate persisting to a database
  if (req.query.fail === 'db') {
    throw new DatabaseError(
      'Could not save new user',
      new Error('Unique constraint violation on column "email"'),
