// 404 catch-all — must be placed AFTER all valid routes
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Any request that did not match a route above lands here.
 * We throw a NotFoundError so that the centralised error handler formats it
 * consistently with all other errors.
 */
app.use((req, _res, next) => {
