assert(nfJSON.error.code === 'USER_NOT_FOUND',  'toJSON().error.code correct');
assert(nfJSON.error.message === 'User not found','toJSON().error.message correct');

// ── ValidationError ───────────────────────────────────────────────────────────
console.log('\n── ValidationError ──');
const fields = { email: 'Invalid format', age: 'Must be positive' };
const ve = new ValidationError('Validation failed', fields);
assert(ve instanceof Error,            'is an instance of Error');
assert(ve instanceof AppError,         'is an instance of AppError');
assert(ve instanceof ValidationError,  'is an instance of ValidationError');
assert(ve.statusCode === 422,          'statusCode = 422');
assert(ve.code === 'VALIDATION_ERROR', 'code = VALIDATION_ERROR');
assert(ve.name === 'ValidationError',  'name = ValidationError');
assert(ve.isOperational === true,      'isOperational = true');
assert(ve.fields === fields,           'fields reference stored');

const veJSON = ve.toJSON();
assert(veJSON.error.fields.email === 'Invalid format', 'toJSON includes field errors');
assert(veJSON.error.fields.age === 'Must be positive', 'toJSON includes all field errors');

// ValidationError with no fields → no `fields` key in JSON
const veSimple = new ValidationError('Bad input');
const veSimpleJSON = veSimple.toJSON();
assert(!('fields' in veSimpleJSON.error), 'no fields key when fields map is empty');

const veDefault = new ValidationError();
assert(veDefault.message === 'Validation failed', 'default message');
assert(veDefault.statusCode === 422, 'default statusCode = 422');

// ── DatabaseError ─────────────────────────────────────────────────────────────
console.log('\n── DatabaseError ──');
const cause = new Error('Connection refused');
const de = new DatabaseError('DB query failed', cause);
assert(de instanceof Error,         'is an instance of Error');
assert(de instanceof AppError,      'is an instance of AppError');
assert(de instanceof DatabaseError, 'is an instance of DatabaseError');
assert(de.statusCode === 503,       'statusCode = 503');
assert(de.code === 'DATABASE_ERROR','code = DATABASE_ERROR');
assert(de.name === 'DatabaseError', 'name = DatabaseError');
assert(de.isOperational === true,   'isOperational = true');
assert(de.cause === cause,          'cause stored for server-side logging');

const deJSON = de.toJSON();
assert(deJSON.error.code === 'DATABASE_ERROR',   'toJSON().error.code correct');
assert(deJSON.error.message === 'DB query failed','toJSON().error.message correct');
assert(!('cause' in deJSON.error),               'cause NOT exposed in toJSON()');

const deDefault = new DatabaseError();
assert(deDefault.message === 'Database operation failed', 'default message');
assert(deDefault.cause === null, 'default cause = null');

// ── instanceof discrimination ─────────────────────────────────────────────────
console.log('\n── instanceof discrimination ──');
assert(!(nf instanceof ValidationError), 'NotFoundError is not a ValidationError');
assert(!(nf instanceof DatabaseError),   'NotFoundError is not a DatabaseError');
assert(!(ve instanceof NotFoundError),   'ValidationError is not a NotFoundError');
assert(!(de instanceof NotFoundError),   'DatabaseError is not a NotFoundError');

// ── Custom error code passthrough ─────────────────────────────────────────────
console.log('\n── Custom error codes ──');
const customNF = new NotFoundError('Product missing', 'PRODUCT_NOT_FOUND');
assert(customNF.code === 'PRODUCT_NOT_FOUND', 'NotFoundError accepts custom code');
const customDB = new DatabaseError('Timeout', null, 'DB_TIMEOUT');
assert(customDB.code === 'DB_TIMEOUT', 'DatabaseError accepts custom code');

