/**
 * errors.js
 * ─────────────────────────────────────────────────────────────────────────────
 * Centralised custom error classes for the Express application.
 *
 * Each class extends the built-in Error and carries:
 *   • statusCode  – the HTTP status code to send to the client
 *   • isOperational – true for "expected" errors (safe to surface to clients),
 *                     false for programmer/infrastructure errors that should be
 *                     treated as unhandled and may warrant a process restart.
 *
 * Usage (inside a route or middleware):
 *
 *   const { NotFoundError, ValidationError, DatabaseError } = require('./errors');
 *
 *   throw new NotFoundError('User not found');
 *   throw new ValidationError('Email is required');
 *   throw new DatabaseError('Connection timed out');
 */

'use strict';

// ─── Base application error ───────────────────────────────────────────────────

class AppError extends Error {
  /**
   * @param {string}  message       - Human-readable description of the problem.
   * @param {number}  statusCode    - HTTP status code (default: 500).
   * @param {boolean} isOperational - Whether this is an expected, operational
   *                                  error (default: true).
   */
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);

    // Maintain the correct constructor name in stack traces.
    this.name = this.constructor.name;

    this.statusCode = statusCode;
    this.isOperational = isOperational;

    // Capture a clean stack trace that omits this constructor call itself.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ─── 404 Not Found ────────────────────────────────────────────────────────────

/**
 * Thrown when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User with id 42 not found');
 *   // → HTTP 404  { error: 'Not Found', message: 'User with id 42 not found' }
 */
class NotFoundError extends AppError {
  /**
   * @param {string} message - Defaults to a generic "Resource not found" message.
   */
  constructor(message = 'Resource not found') {
    super(message, 404);
  }
}

// ─── 422 Validation Error ─────────────────────────────────────────────────────

/**
 * Thrown when incoming request data fails validation (missing fields, wrong
 * types, constraint violations, etc.).
 *
 * @example
 *   throw new ValidationError('Email address is required');
 *   // → HTTP 422  { error: 'Validation Error', message: 'Email address is required' }
 */
class ValidationError extends AppError {
  /**
   * @param {string}   message - Description of what failed validation.
   * @param {string[]} [fields]  - Optional list of field names that are invalid,
   *                               included in the response for client convenience.
   */
  constructor(message = 'Validation failed', fields = []) {
    super(message, 422);
    // Carry invalid field names so the error handler can forward them to clients.
    this.fields = fields;
  }
}

// ─── 503 Database Error ───────────────────────────────────────────────────────

/**
 * Thrown when a database operation fails (connection error, query timeout,
 * constraint violation that was not caught earlier, etc.).
 *
 * Marked as NON-operational (isOperational = false) because a DB failure is
 * typically an infrastructure problem that warrants operator attention and
 * should NOT leak internal details to clients.
 *
 * @example
 *   throw new DatabaseError('Connection pool exhausted');
 *   // → HTTP 503  { error: 'Service Unavailable', message: 'A database error occurred' }
 */
class DatabaseError extends AppError {
  /**
   * @param {string} message - Internal description (logged server-side, NOT
   *                           forwarded to the client).
   */
  constructor(message = 'A database error occurred') {
    // isOperational = false → signals that this may be a critical failure.
    super(message, 503, false);
  }
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

/**
 * app.js
 * ─────────────────────────────────────────────────────────────────────────────
 * Express application with centralised error handling.
 *
 * Error flow
 * ──────────
 * Routes throw (or pass) custom AppError subclasses instead of writing inline
 * res.status().json() error responses.  Two dedicated middleware functions at
 * the bottom of the stack take care of every error in one place:
 *
 *   1. 404 catcher  – converts any request that fell through all routes into a
 *                     NotFoundError and forwards it to the error handler.
 *   2. Error handler – formats and sends the final JSON error response, with
 *                      different verbosity for operational vs. unexpected errors.
 */

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

// ─── Body parsing ─────────────────────────────────────────────────────────────
app.use(express.json());

// =============================================================================
// Routes
// =============================================================================

// ─── GET /health ─────────────────────────────────────────────────────────────
/**
 * Simple liveness probe.
 * Always returns 200 – no error paths needed here.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ─── GET /users ──────────────────────────────────────────────────────────────
/**
 * Returns the full list of users.
 *
 * Simulated error cases (triggered via query params for demonstration):
 *   ?simulateDb=1   → throws DatabaseError  (e.g. DB connection lost)
 */
app.get('/users', (req, res) => {
  // ── Simulated DatabaseError ──────────────────────────────────────────────
  if (req.query.simulateDb) {
    throw new DatabaseError('Failed to query users table: connection timed out');
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ─── GET /users/:id ──────────────────────────────────────────────────────────
/**
 * Returns a single user by numeric id.
 *
 * Throws:
 *   ValidationError – when :id is not a positive integer.
 *   NotFoundError   – when no user matches the given id.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  // ── Validate the id parameter ────────────────────────────────────────────
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('User id must be a positive integer', ['id']);
  }

  // ── Simulated data store ─────────────────────────────────────────────────
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find((u) => u.id === id);

  // ── Resource guard ───────────────────────────────────────────────────────
  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`);
  }

  res.json(user);
});

// ─── POST /users ─────────────────────────────────────────────────────────────
/**
 * Creates a new user.
 *
 * Expected body: { name: string, email: string }
 *
 * Throws:
 *   ValidationError – when required fields are absent or malformed.
 *   DatabaseError   – simulated persistence failure.
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};
  const invalidFields = [];

  // ── Validate required fields ─────────────────────────────────────────────
  if (!name || typeof name !== 'string' || name.trim() === '') {
    invalidFields.push('name');
  }
  if (!email || typeof email !== 'string' || !email.includes('@')) {
    invalidFields.push('email');
  }

  if (invalidFields.length > 0) {
    throw new ValidationError(
      `Missing or invalid fields: ${invalidFields.join(', ')}`,
      invalidFields,
    );
  }

  // ── Simulated DatabaseError ──────────────────────────────────────────────
  if (req.query.simulateDb) {
    throw new DatabaseError('Failed to insert user: write conflict');
  }

  // ── Return the newly created resource (HTTP 201) ─────────────────────────
  const newUser = { id: 3, name: name.trim(), email: email.trim() };
  res.status(201).json(newUser);
});

// =============================================================================
// Centralised error-handling middleware
// =============================================================================

// ─── 404 catcher ─────────────────────────────────────────────────────────────
/**
 * Catches every request that did not match any route above and converts it into
 * a structured NotFoundError before passing it to the error handler.
 *
 * Must be placed AFTER all routes.
 */
app.use((req, res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`));
});

// ─── Global error handler ─────────────────────────────────────────────────────
/**
 * Single, authoritative place for turning errors into HTTP responses.
 *
 * Behaviour by error type
 * ───────────────────────
 * • AppError (isOperational = true)
 *     statusCode and message are forwarded to the client as-is.
 *     These are "expected" errors (bad input, missing resource, etc.).
 *
 * • DatabaseError / AppError (isOperational = false)
 *     statusCode is forwarded but the internal message is kept server-side.
 *     The client receives only a generic "Service Unavailable" message to
 *     avoid leaking infrastructure details.
 *
 * • Unknown / unexpected errors
 *     Always respond with 500 Internal Server Error.
 *     The original error is logged for debugging but never sent to the client.
 *
 * The four-argument signature (err, req, res, next) is required by Express to
 * recognise this as an error-handling middleware.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── Always log the full error server-side ─────────────────────────────────
  console.error(`[${new Date().toISOString()}] ${err.name}: ${err.message}`);
  if (process.env.NODE_ENV !== 'production') {
    console.error(err.stack);
  }

  // ── Determine response shape based on error type ──────────────────────────
  if (err instanceof AppError) {
    // Map our custom error names to client-friendly titles.
    const errorTitles = {
      NotFoundError: 'Not Found',
      ValidationError: 'Validation Error',
      DatabaseError: 'Service Unavailable',
      AppError: 'Application Error',
    };

    const title = errorTitles[err.name] ?? 'Error';

    // Non-operational errors (e.g. DatabaseError) hide internal details.
    const clientMessage = err.isOperational
      ? err.message
      : 'An unexpected error occurred. Please try again later.';

    const body = {
      error: title,
      message: clientMessage,
      ...(err.statusCode && { statusCode: err.statusCode }),
    };

    // Include invalid field names for ValidationErrors (helpful for clients).
    if (err instanceof ValidationError && err.fields?.length > 0) {
      body.fields = err.fields;
    }

    return res.status(err.statusCode).json(body);
  }

  // ── Fallback: completely unexpected / programmer error ────────────────────
  res.status(500).json({
    error: 'Internal Server Error',
    message: 'An unexpected error occurred. Please try again later.',
    statusCode: 500,
  });
});

// =============================================================================
// Server bootstrap
// =============================================================================

/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT ?? 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

