/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Every class extends the base AppError, which carries:
 *  - statusCode  → HTTP status sent to the client
 *  - isOperational → true  = known/expected error (safe to expose message)
 *                    false = programmer / unexpected error (hide internals)
 */

'use strict';

// ---------------------------------------------------------------------------
// Base class
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message        - Human-readable description.
   * @param {number}  statusCode     - HTTP status code (default 500).
   * @param {boolean} isOperational  - Whether this is an expected runtime
   *                                   error (true) or a bug (false).
   */
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);

    // Maintains proper prototype chain for `instanceof` checks
    Object.setPrototypeOf(this, new.target.prototype);

    this.name       = this.constructor.name;
    this.statusCode = statusCode;
    this.status     = statusCode >= 500 ? 'error' : 'fail';
    this.isOperational = isOperational;

    // Omit the constructor call from the stack trace
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 – Resource not found
// ---------------------------------------------------------------------------

class NotFoundError extends AppError {
  /**
   * @param {string} [resource] - Optional name of the missing resource,
